1	/**
2	 * App evals: Twyne's model-backed features, driven through MCP and the CLI.
3	 *
4	 *   bun run eval:app                                  # every suite, mock model
5	 *   bun run eval:app -- --suite room --model notorganic --judge notorganic --arize --trace
6	 *   bun run eval:app -- --target live --suite rubric  # a deployment, via TWYNE_API_URL
7	 *
8	 * See evals/app/README.md for the suites, the scores and the Arize hand-off.
9	 */
10	import { mkdir, writeFile } from "node:fs/promises";
11	import { join } from "node:path";
12	import { fileURLToPath } from "node:url";
13	import { parseArgs } from "node:util";
14	import {
15	  corpusHash,
16	  ensureDataset,
17	  uploadExperiment,
18	  withCaseSpan,
19	  type ExperimentRun,
20	} from "./arize";
21	import { connectMcp, type Connection, type McpDriver } from "./drivers";
22	import { createJudge, type JudgeMode } from "./judges";
23	import {
24	  startLocalApp,
25	  type AppModelMode,
26	  type LocalApp,
27	  type ResearchMode,
28	  type SystemOneMode,
29	  type UsageTotals,
30	} from "./local-app";
31	import { TwyneClient } from "../../packages/twyne-tools/src/client";
32	import { mean, type Score } from "./scoring";
33	import { dossierSuite } from "./suites/dossier";
34	import { interviewSuite } from "./suites/interview";
35	import { researchSourcesSuite, researchTargetsSuite } from "./suites/research";
36	import { roomSuite } from "./suites/room";
37	import { rewriteSuite } from "./suites/rewrite";
38	import { rubricSuite } from "./suites/rubric";
39	import type { ScoredCase, Suite } from "./suites/types";
40	
41	const SUITES = {
42	  room: roomSuite,
43	  rubric: rubricSuite,
44	  rewrite: rewriteSuite,
45	  dossier: dossierSuite,
46	  interview: interviewSuite,
47	  "research-targets": researchTargetsSuite,
48	  "research-sources": researchSourcesSuite,
49	} as const satisfies Record<string, Suite<{ case_id: string }>>;
50	
51	type SuiteName = keyof typeof SUITES;
52	
53	const HELP = `Twyne app evals
54	
55	Usage: bun evals/app/run.ts [options]
56	
57	  --suite NAMES        room, rubric, rewrite, dossier, interview, research-targets,
58	                       research-sources, or all (default all)
59	  --target local|live  in-process app (default) or TWYNE_API_URL + TWYNE_ACCESS_TOKEN
60	  --model MODE         local app's hosted model: mock (default), openai-compatible, notorganic
61	  --system-one MODE    review-gate judgements: mock, direct (TYPESAFE_API_KEY) or off
62	                       (default: mock with the mock model, direct when a key is set)
63	  --research MODE      auto-research search: mock, notorganic, keenable (KEENABLE_API_KEY),
64	                       custom (TWYNE_APP_SEARCH_URL) or off
65	                       (default: mock with the mock model, notorganic with notorganic)
66	  --driver mcp|mcp-stdio  MCP in-process (default) or twyne-mcp over stdio
67	  --judge MODE         none (default), notorganic, openai-compatible
68	  --jev                add Jev (calibrated judgements) and Clairic (typed extraction)
69	                       evaluators, asked through the app's own System One and extraction
70	  --case IDS           only these case_ids (comma-separated)
71	  --limit N            first N cases per suite
72	  --concurrency N      cases in flight per suite (default 2)
73	  --arize              upload each suite as an Arize dataset + experiment (ax CLI)
74	  --arize-space ID     Arize space (default ARIZE_SPACE_ID)
75	  --trace              export the app's spans to Arize (ARIZE_API_KEY, ARIZE_SPACE_ID)
76	  --project NAME       Arize tracing project (default twyne-app-evals)
77	  --experiment NAME    experiment name prefix (default app-<suite>-<model>-<time>)
78	  --out DIR            report directory (default reports/app-evals)
79	  --strict             exit 1 when any case fails to run
80	`;
81	
82	export interface SuiteReport {
83	  suite: string;
84	  surface: string;
85	  experiment: string;
86	  target: string;
87	  model: string;
88	  driver: string;
89	  judge: string;
90	  startedAt: string;
91	  summary: Record<string, { mean: number | null; n: number }>;
92	  errors: number;
93	  /** Hosted calls the in-process app made for this suite. */
94	  usage?: Omit<UsageTotals, "costMicrousd"> & { costMicrousd: number | null };
95	  /** What Not Organic billed for the suite (notorganic mode only). */
96	  billed?: { microusd: number; settled: number; unresolved: number } | null;
97	  arize?: { dataset: string; datasetId: string; experimentId: string | null };
98	  cases: Array<{
99	    case_id: string;
100	    ok: boolean;
101	    /** Never started: the run stopped after repeated provider failures. */
102	    skipped?: boolean;
103	    error?: string;
104	    latencyMs: number;
105	    traceId: string | null;
106	    scores: Record<string, Score>;
107	    output: string;
108	    raw: unknown;
109	  }>;
110	}
111	
112	export interface RunOptions {
113	  suites: SuiteName[];
114	  target: "local" | "live";
115	  model: AppModelMode;
116	  systemOne?: SystemOneMode;
117	  research?: ResearchMode;
118	  driver: McpDriver["kind"];
119	  judge: JudgeMode;
120	  /** Add Jev and Clairic evaluators (through the app's own paths). */
121	  jev?: boolean;
122	  caseIds?: string[];
123	  limit?: number;
124	  concurrency: number;
125	  arize: boolean;
126	  arizeSpace?: string;
127	  trace: boolean;
128	  project: string;
129	  experiment?: string;
130	  out?: string;
131	  env: Readonly<Record<string, string | undefined>>;
132	  log?: (line: string) => void;
133	}
134	
135	async function pool<T, R>(
136	  items: T[],
137	  limit: number,
138	  worker: (item: T) => Promise<R>,
139	): Promise<R[]> {
140	  const results: R[] = new Array(items.length);
141	  let next = 0;
142	  const lanes = Array.from({ length: Math.max(1, Math.min(limit, items.length)) }, async () => {
143	    while (next < items.length) {
144	      const index = next++;
145	      results[index] = await worker(items[index]);
146	    }
147	  });
148	  await Promise.all(lanes);
149	  return results;
150	}
151	
152	function stamp(): string {
153	  return new Date().toISOString().replace(/[-:]/g, "").replace(/\..+/, "").replace("T", "-");
154	}
155	
156	/** Rate limits are per writer, so a live run retries what the limiter refused. */
157	async function withRetry<T>(live: boolean, task: () => Promise<T>): Promise<T> {
158	  for (let attempt = 0; ; attempt++) {
159	    try {
160	      return await task();
161	    } catch (error) {
162	      const message = error instanceof Error ? error.message : String(error);
163	      if (!live || attempt >= 3 || !/rate|429|too many|slow down/i.test(message))
164	        throw error;
165	      await new Promise((done) => setTimeout(done, 20_000 * (attempt + 1)));
166	    }
167	  }
168	}
169	
170	function summarize(cases: SuiteReport["cases"]): SuiteReport["summary"] {
171	  const names = [...new Set(cases.flatMap((c) => Object.keys(c.scores)))];
172	  return Object.fromEntries(
173	    names.map((name) => {
174	      const values = cases.map((c) => c.scores[name]?.score ?? null);
175	      return [
176	        name,
177	        { mean: mean(values), n: values.filter((v) => v !== null).length },
178	      ];
179	    }),
180	  );
181	}
182	
183	function printReport(report: SuiteReport, log: (line: string) => void): void {
184	  log(
185	    `\n${report.suite} — ${report.surface} — ${report.cases.length} case(s), ${report.errors} error(s)`,
186	  );
187	  if (report.usage?.calls)
188	    log(
189	      `  hosted calls ${report.usage.calls}, tokens ${report.usage.inputTokens} in / ${report.usage.outputTokens} out` +
190	        (report.usage.costMicrousd !== null
191	          ? `, est. $${(report.usage.costMicrousd / 1e6).toFixed(4)}`
192	          : ""),
193	    );
194	  if (report.billed)
195	    log(
196	      `  billed by Not Organic $${(report.billed.microusd / 1e6).toFixed(4)} (${report.billed.settled} settled` +
197	        (report.billed.unresolved ? `, ${report.billed.unresolved} still settling` : "") +
198	        ")",
199	    );
200	  for (const [name, { mean: value, n }] of Object.entries(report.summary)) {
201	    const shown = value === null ? "   -" : value.toFixed(2);
202	    log(`  ${name.padEnd(24)} ${shown}  (n=${n})`);
203	  }
204	  for (const failed of report.cases.filter((c) => !c.ok && !c.skipped))
205	    log(`  ✗ ${failed.case_id}: ${failed.error}`);
206	  const skipped = report.cases.filter((c) => c.skipped).length;
207	  if (skipped) log(`  ⏸ ${skipped} case(s) not run: ${report.cases.find((c) => c.skipped)?.error}`);
208	}
209	
210	export async function runAppEvals(options: RunOptions): Promise<SuiteReport[]> {
211	  const log = options.log ?? ((line: string) => console.log(line));
212	  const live = options.target === "live";
213	  const arizeSpace = options.arizeSpace ?? options.env.ARIZE_SPACE_ID;
214	  if (options.arize && !arizeSpace)
215	    throw new Error("--arize needs --arize-space or ARIZE_SPACE_ID");
216	
217	  const tracing = options.trace
218	    ? {
219	        apiKey: options.env.ARIZE_API_KEY ?? "",
220	        spaceId: options.env.ARIZE_SPACE_ID ?? "",
221	        projectName: options.project,
222	        region: options.env.ARIZE_REGION,
223	      }
224	    : null;
225	  if (tracing && (!tracing.apiKey || !tracing.spaceId))
226	    throw new Error("--trace needs ARIZE_API_KEY and ARIZE_SPACE_ID");
227	
228	  const judge = createJudge(options.judge, options.env);
229	  let app: LocalApp | null = null;
230	  let shared: Connection | null = null;
231	  if (live) {
232	    const apiUrl = options.env.TWYNE_API_URL;
233	    const token = options.env.TWYNE_ACCESS_TOKEN;
234	    if (!apiUrl || !token)
235	      throw new Error("--target live needs TWYNE_API_URL and TWYNE_ACCESS_TOKEN");
236	    shared = { apiUrl, token };
237	    if (tracing) {
238	      process.env.ARIZE_API_KEY = tracing.apiKey;
239	      process.env.ARIZE_SPACE_ID = tracing.spaceId;
240	      process.env.ARIZE_PROJECT_NAME = tracing.projectName;
241	      if (tracing.region) process.env.ARIZE_REGION = tracing.region;
242	    }
243	  } else {
244	    app = await startLocalApp({
245	      model: options.model,
246	      systemOne: options.systemOne,
247	      research: options.research,
248	      env: options.env,
249	      tracing,
250	    });
251	  }
252	  // Registers the OpenInference exporter when the Arize keys are present.
253	  const { flushArize } = await import("../../convex/arizeTracing");
254	
255	  const modelLabel = live ? "deployment" : (app?.modelLabel ?? options.model);
256	  if (options.jev && !app)
257	    throw new Error("--jev runs Jev and Clairic through the in-process app; use --target local");
258	  const scoreContext = {
259	    judge,
260	    jev: options.jev && app ? app.judge : null,
261	    extract: options.jev && app ? app.extract : null,
262	  };
263	  const reports: SuiteReport[] = [];
264	  // Out of credit and an outage look the same from here: the app reports the
265	  // provider unavailable. Three in a row stops the suite, so a drained wallet
266	  // ends it cleanly instead of filling the experiment with failures.
267	  let providerFailures = 0;
268	  let stopped: string | null = null;
269	  try {
270	    for (const suiteName of options.suites) {
271	      const suite = SUITES[suiteName] as Suite<{ case_id: string }>;
272	      // A provider that fails one suite's alias can still serve the next.
273	      providerFailures = 0;
274	      stopped = null;
275	      let cases = suite.load();
276	      if (options.caseIds?.length)
277	        cases = cases.filter((c) => options.caseIds?.includes(c.case_id));
278	      if (options.limit) cases = cases.slice(0, options.limit);
279	      if (cases.length === 0) continue;
280	
281	      const experiment =
282	        options.experiment
283	          ? `${options.experiment}-${suiteName}`
284	          : `app-${suiteName}-${options.target === "live" ? "live" : options.model}-${stamp()}`;
285	      log(`▸ ${suiteName}: ${cases.length} case(s) via ${suite.surface} → ${modelLabel}`);
286	
287	      const usageBefore = await app?.usage();
288	      const suiteStarted = Date.now();
289	      let sharedMcp: McpDriver | null = null;
290	      if (shared) sharedMcp = await connectMcp(shared, options.driver);
291	
292	      const runs = await pool(cases, live ? 1 : options.concurrency, async (testCase) => {
293	        if (stopped)
294	          return {
295	            case_id: testCase.case_id,
296	            testCase,
297	            ok: false,
298	            skipped: true,
299	            error: stopped,
300	            latencyMs: 0,
301	            traceId: null,
302	            scores: {} as Record<string, Score>,
303	            output: `[skipped] ${stopped}`,
304	            raw: null,
305	          };
306	        const connection: Connection = shared ?? {
307	          apiUrl: app!.url,
308	          token: (await app!.newWriter(testCase.case_id)).token,
309	          ...(options.driver === "mcp" ? { fetch: app!.fetch } : {}),
310	        };
311	        const mcp = sharedMcp ?? (await connectMcp(connection, options.driver));
312	        const started = Date.now();
313	        try {
314	          const { value, traceId } = await withCaseSpan(
315	            {
316	              suite: suiteName,
317	              caseId: testCase.case_id,
318	              experiment,
319	              input: JSON.stringify(suite.example(testCase)).slice(0, 20_000),
320	            },
321	            async () => {
322	              const client = new TwyneClient({
323	                apiUrl: connection.apiUrl,
324	                accessToken: connection.token,
325	                fetch: connection.fetch,
326	              });
327	              const run = await withRetry(live, () =>
328	                suite.run({ mcp, connection, client }, testCase),
329	              );
330	              return { value: run, output: run.output };
331	            },
332	          );
333	          const latencyMs = Date.now() - started;
334	          const scores = await suite.score(scoreContext, testCase, value.raw);
335	          providerFailures = 0;
336	          log(`  ✓ ${testCase.case_id} (${(latencyMs / 1000).toFixed(1)}s)`);
337	          return {
338	            case_id: testCase.case_id,
339	            testCase,
340	            ok: true,
341	            latencyMs,
342	            traceId,
343	            scores,
344	            output: value.output,
345	            raw: value.raw,
346	          };
347	        } catch (error) {
348	          const message = error instanceof Error ? error.message : String(error);
349	          log(`  ✗ ${testCase.case_id}: ${message}`);
350	          if (/unavailable|insufficient|quota|credit|402/i.test(message)) {
351	            providerFailures += 1;
352	            if (providerFailures >= 3)
353	              stopped = "stopped after 3 consecutive provider failures (out of credit or provider down)";
354	          }
355	          return {
356	            case_id: testCase.case_id,
357	            testCase,
358	            ok: false,
359	            error: message,
360	            latencyMs: Date.now() - started,
361	            traceId: null,
362	            scores: {} as Record<string, Score>,
363	            output: `[error] ${message}`,
364	            raw: null,
365	          };
366	        } finally {
367	          if (!sharedMcp) await mcp.close();
368	        }
369	      });
370	      await sharedMcp?.close();
371	
372	      const scored: Array<ScoredCase<{ case_id: string }>> = runs
373	        .filter((r) => r.ok)
374	        .map((r) => ({ case: r.testCase, raw: r.raw, scores: r.scores }));
375	      suite.scoreAll?.(scored);
376	      for (const r of runs)
377	        if (!("skipped" in r && r.skipped))
378	          r.scores.harness = { score: r.ok ? 1 : 0, label: r.ok ? "ran" : "error", explanation: r.error };
379	
380	      const report: SuiteReport = {
381	        suite: suiteName,
382	        surface: suite.surface,
383	        experiment,
384	        target: options.target,
385	        model: modelLabel,
386	        driver: options.driver,
387	        judge: judge?.label ?? "none",
388	        startedAt: new Date().toISOString(),
389	        summary: {},
390	        errors: runs.filter((r) => !r.ok && !("skipped" in r && r.skipped)).length,
391	        cases: runs.map(({ testCase: _case, ...rest }) => rest),
392	      };
393	      report.summary = summarize(report.cases);
394	      const usageAfter = await app?.usage();
395	      if (usageBefore && usageAfter) {
396	        const unpriced = usageAfter.unpriced - usageBefore.unpriced;
397	        report.usage = {
398	          calls: usageAfter.calls - usageBefore.calls,
399	          inputTokens: usageAfter.inputTokens - usageBefore.inputTokens,
400	          outputTokens: usageAfter.outputTokens - usageBefore.outputTokens,
401	          unpriced,
402	          // Not Organic aliases carry no local price; the wallet is the ledger.
403	          costMicrousd: unpriced ? null : usageAfter.costMicrousd - usageBefore.costMicrousd,
404	        };
405	      }
406	      if (app && options.model === "notorganic") {
407	        // Settlement lags the response slightly; give the ledger a moment.
408	        await new Promise((done) => setTimeout(done, 3_000));
409	        const billed = await app.billed(suiteStarted, Date.now());
410	        report.billed = billed
411	          ? {
412	              microusd: billed.billedMicrousd,
413	              settled: billed.settledRequests,
414	              unresolved: billed.unresolvedRequests,
415	            }
416	          : null;
417	      }
418	
419	      if (options.arize && arizeSpace) {
420	        const examples = cases.map((c) => suite.example(c) as Record<string, string | number | boolean> & { case_id: string });
421	        const dataset = await ensureDataset(
422	          { space: arizeSpace },
423	          `twyne-app-${suiteName}-${corpusHash(examples)}`,
424	          examples,
425	        );
426	        const experimentRuns: ExperimentRun[] = report.cases.flatMap((c) => {
427	          const exampleId = dataset.examples.get(c.case_id);
428	          if (!exampleId || c.skipped) return [];
429	          return [
430	            {
431	              example_id: exampleId,
432	              output: c.output,
433	              ok: c.ok,
434	              error: c.error,
435	              scores: c.scores,
436	              metadata: {
437	                case_id: c.case_id,
438	                target: report.target,
439	                app_model: report.model,
440	                driver: report.driver,
441	                judge: report.judge,
442	                latency_ms: c.latencyMs,
443	                trace_id: c.traceId,
444	              },
445	            },
446	          ];
447	        });
448	        const created = await uploadExperiment(dataset.id, experiment, experimentRuns);
449	        report.arize = {
450	          dataset: dataset.name,
451	          datasetId: dataset.id,
452	          experimentId: created.id,
453	        };
454	        log(`  ↑ Arize: experiment "${experiment}" on dataset ${dataset.name}`);
455	        if (created.labelOnly.length)
456	          log(`    uploaded as labels (not every case applies): ${created.labelOnly.join(", ")}`);
457	      }
458	
459	      printReport(report, log);
460	      reports.push(report);
461	      if (options.out) {
462	        await mkdir(options.out, { recursive: true });
463	        await writeFile(
464	          join(options.out, `${experiment}.json`),
465	          JSON.stringify(report, null, 2),
466	        );
467	      }
468	    }
469	  } finally {
470	    await flushArize();
471	    await app?.close();
472	  }
473	  return reports;
474	}
475	
476	async function main(): Promise<void> {
477	  const { values } = parseArgs({
478	    options: {
479	      suite: { type: "string", default: "all" },
480	      target: { type: "string", default: "local" },
481	      model: { type: "string", default: "mock" },
482	      "system-one": { type: "string" },
483	      research: { type: "string" },
484	      driver: { type: "string", default: "mcp" },
485	      judge: { type: "string", default: "none" },
486	      jev: { type: "boolean", default: false },
487	      case: { type: "string" },
488	      limit: { type: "string" },
489	      concurrency: { type: "string", default: "2" },
490	      arize: { type: "boolean", default: false },
491	      "arize-space": { type: "string" },
492	      trace: { type: "boolean", default: false },
493	      project: { type: "string", default: "twyne-app-evals" },
494	      experiment: { type: "string" },
495	      out: { type: "string" },
496	      strict: { type: "boolean", default: false },
497	      help: { type: "boolean", short: "h", default: false },
498	    },
499	  });
500	  if (values.help) {
501	    console.log(HELP);
502	    return;
503	  }
504	  const suites = (values.suite === "all" ? Object.keys(SUITES) : values.suite.split(","))
505	    .map((s) => s.trim())
506	    .filter(Boolean) as SuiteName[];
507	  for (const suite of suites)
508	    if (!(suite in SUITES)) throw new Error(`Unknown suite: ${suite}`);
509	  const choice = <T extends string>(value: string, allowed: readonly T[], flag: string): T => {
510	    if (!allowed.includes(value as T))
511	      throw new Error(`--${flag} must be one of ${allowed.join(", ")}`);
512	    return value as T;
513	  };
514	  const reports = await runAppEvals({
515	    suites,
516	    target: choice(values.target, ["local", "live"], "target"),
517	    model: choice(values.model, ["mock", "openai-compatible", "notorganic"], "model"),
518	    systemOne: values["system-one"]
519	      ? choice<SystemOneMode>(values["system-one"], ["mock", "direct", "off"], "system-one")
520	      : undefined,
521	    research: values.research
522	      ? choice<ResearchMode>(values.research, ["mock", "notorganic", "keenable", "custom", "off"], "research")
523	      : undefined,
524	    driver: choice(values.driver, ["mcp", "mcp-stdio"], "driver"),
525	    judge: choice(values.judge, ["none", "notorganic", "openai-compatible"], "judge"),
526	    jev: values.jev,
527	    caseIds: values.case?.split(",").map((s) => s.trim()).filter(Boolean),
528	    limit: values.limit ? Number(values.limit) : undefined,
529	    concurrency: Number(values.concurrency),
530	    arize: values.arize,
531	    arizeSpace: values["arize-space"],
532	    trace: values.trace,
533	    project: values.project,
534	    experiment: values.experiment,
535	    out:
536	      values.out ??
537	      join(fileURLToPath(new URL("../../reports/app-evals", import.meta.url))),
538	    env: { ...process.env },
539	  });
540	  const errors = reports.reduce((sum, r) => sum + r.errors, 0);
541	  if (values.strict && errors > 0) process.exitCode = 1;
542	}
543	
544	if (import.meta.main) {
545	  main().catch((error) => {
546	    console.error(`[twyne:app-evals] ${error instanceof Error ? error.message : String(error)}`);
547	    process.exit(1);
548	  });
549	}
