1	/**
2	 * Deterministic checks shared by the app eval suites. None of these call a
3	 * model, so a regression in them is a regression in the app, not judge noise.
4	 */
5	import { clampForContext, DRAFT_CONTEXT_CHARS } from "../../convex/agentPrompts";
6	
7	export interface Score {
8	  /** 0..1, or null when the check does not apply to this case. */
9	  score: number | null;
10	  label?: string;
11	  explanation?: string;
12	}
13	
14	export function words(text: string): string[] {
15	  return text.trim().split(/\s+/).filter(Boolean);
16	}
17	
18	/** Whitespace and typography folded, so a verbatim match survives both. */
19	export function fold(text: string): string {
20	  return text
21	    .replace(/[“”]/g, '"')
22	    .replace(/[‘’]/g, "'")
23	    .replace(/[–—]/g, "-")
24	    .replace(/\s+/g, " ")
25	    .trim();
26	}
27	
28	export function contains(haystack: string, needle: string): boolean {
29	  const n = fold(needle);
30	  return n.length > 0 && fold(haystack).includes(n);
31	}
32	
33	const STOPWORDS = new Set(
34	  "a an the this that these those of in on at to for and or but is are was were be been it its as by with from no not there their".split(" "),
35	);
36	
37	function contentWords(text: string): string[] {
38	  return fold(text)
39	    .toLowerCase()
40	    .replace(/[^a-z0-9' ]+/g, " ")
41	    .split(/\s+/)
42	    .map((word) => word.replace(/^'+|'+$/g, ""))
43	    .filter((word) => word && !STOPWORDS.has(word))
44	    .map((word) =>
45	      word.length <= 3
46	        ? word
47	        : word.endsWith("ies")
48	          ? `${word.slice(0, -3)}y`
49	          : word.endsWith("s") && !word.endsWith("ss")
50	            ? word.slice(0, -1)
51	            : word,
52	    );
53	}
54	
55	/**
56	 * Does `text` keep `fact`? Every content word of the fact must survive, so
57	 * "the rail" is kept by "the cold rail" and "store of value" by "stores of
58	 * value", while a dropped name or number is not.
59	 */
60	export function keepsFact(text: string, fact: string): boolean {
61	  const kept = new Set(contentWords(text));
62	  const needed = contentWords(fact);
63	  return needed.length > 0 && needed.every((word) => kept.has(word));
64	}
65	
66	/** Character span of `passage` in the folded draft, or null. */
67	export function span(
68	  draft: string,
69	  passage: string,
70	): { start: number; end: number } | null {
71	  const d = fold(draft);
72	  const p = fold(passage);
73	  if (!p) return null;
74	  const start = d.indexOf(p);
75	  return start < 0 ? null : { start, end: start + p.length };
76	}
77	
78	/** Do two passages of the same draft overlap by at least `min` of the shorter? */
79	export function spansOverlap(
80	  draft: string,
81	  a: string,
82	  b: string,
83	  min = 0.3,
84	): boolean {
85	  const sa = span(draft, a);
86	  const sb = span(draft, b);
87	  if (!sa || !sb) return false;
88	  const shared = Math.min(sa.end, sb.end) - Math.max(sa.start, sb.start);
89	  if (shared <= 0) return false;
90	  return shared / Math.min(sa.end - sa.start, sb.end - sb.start) >= min;
91	}
92	
93	function ngrams(text: string, n: number): Set<string> {
94	  const tokens = fold(text)
95	    .toLowerCase()
96	    .replace(/[^a-z0-9' ]+/g, " ")
97	    .split(/\s+/)
98	    .filter(Boolean);
99	  const out = new Set<string>();
100	  for (let i = 0; i + n <= tokens.length; i++)
101	    out.add(tokens.slice(i, i + n).join(" "));
102	  return out;
103	}
104	
105	/** Does `text` reproduce any run of `n` consecutive words from `passage`? */
106	export function sharesRun(text: string, passage: string, n = 5): boolean {
107	  const runs = ngrams(passage, n);
108	  for (const gram of ngrams(text, n)) if (runs.has(gram)) return true;
109	  return false;
110	}
111	
112	export function jaccard(a: string, b: string, n = 1): number {
113	  const x = ngrams(a, n);
114	  const y = ngrams(b, n);
115	  if (x.size === 0 && y.size === 0) return 1;
116	  let shared = 0;
117	  for (const gram of x) if (y.has(gram)) shared += 1;
118	  return shared / (x.size + y.size - shared);
119	}
120	
121	/** 1 minus the mean pairwise trigram overlap: how differently the notes read. */
122	export function distinctness(texts: string[]): number | null {
123	  if (texts.length < 2) return null;
124	  let total = 0;
125	  let pairs = 0;
126	  for (let i = 0; i < texts.length; i++)
127	    for (let j = i + 1; j < texts.length; j++) {
128	      total += jaccard(texts[i], texts[j], 3);
129	      pairs += 1;
130	    }
131	  return 1 - total / pairs;
132	}
133	
134	/**
135	 * Would `passage` reach the editors? Runs the app's own `clampForContext`
136	 * with its `DRAFT_CONTEXT_CHARS` budget, so the eval and the prompt cannot
137	 * disagree about what was shown.
138	 */
139	export function visibleToEditors(draft: string, passage: string): boolean {
140	  return contains(clampForContext(draft, DRAFT_CONTEXT_CHARS), passage);
141	}
142	
143	export function ratio(hit: number, total: number): number | null {
144	  return total > 0 ? hit / total : null;
145	}
146	
147	export function mean(values: Array<number | null | undefined>): number | null {
148	  const present = values.filter((v): v is number => typeof v === "number");
149	  return present.length
150	    ? present.reduce((sum, v) => sum + v, 0) / present.length
151	    : null;
152	}
153	
154	export function pass(ok: boolean, explanation?: string): Score {
155	  return { score: ok ? 1 : 0, label: ok ? "pass" : "fail", explanation };
156	}
