1	/**
2	 * LLM-as-judge for the app evals.
3	 *
4	 * The faithfulness and helpfulness rubrics are imported from `evals/judge.ts`
5	 * unchanged, so a score here means the same thing as a score from
6	 * `bun run eval:judge` and from the two Arize template evaluators it mirrors
7	 * (faithfulness-to-draft, feedback-helpfulness). The rubrics that only make
8	 * sense with the app's corpus (planted weaknesses, rewrite improvement) are
9	 * defined below.
10	 *
11	 * Judges are optional. `--judge none` scores with the deterministic checks
12	 * alone, which is what CI and the mock model use.
13	 */
14	import { createEvalClient } from "../llm-client";
15	import {
16	  CHOICES,
17	  FAITHFULNESS_TEMPLATE,
18	  HELPFULNESS_TEMPLATE,
19	  judgeSystemPrompt,
20	  parseVerdict,
21	  type Verdict,
22	} from "../judge";
23	import type { Score } from "./scoring";
24	
25	export type JudgeMode = "none" | "notorganic" | "openai-compatible";
26	
27	export interface Judge {
28	  label: string;
29	  complete(system: string, user: string, signal: AbortSignal): Promise<string>;
30	}
31	
32	type Env = Readonly<Record<string, string | undefined>>;
33	
34	export function createJudge(mode: JudgeMode, env: Env): Judge | null {
35	  if (mode === "none") return null;
36	  if (mode === "notorganic") {
37	    const complete = createEvalClient(env);
38	    const model = env.JUDGE_MODEL ?? "reasoning";
39	    return {
40	      label: `notorganic:${model}`,
41	      complete: (system, user, signal) =>
42	        complete(
43	          {
44	            model,
45	            temperature: 0,
46	            // Same headroom as the app (NO_OUTPUT_CEILING in convex/agents.ts):
47	            // the gateway's default lets a reasoning model think past it.
48	            max_tokens: 16_000,
49	            messages: [
50	              { role: "system", content: system },
51	              { role: "user", content: user },
52	            ],
53	          },
54	          signal,
55	        ),
56	    };
57	  }
58	  const baseUrl = env.TWYNE_JUDGE_BASE_URL?.trim().replace(/\/+$/, "");
59	  const model = env.TWYNE_JUDGE_MODEL?.trim();
60	  if (!baseUrl || !model)
61	    throw new Error(
62	      "TWYNE_JUDGE_BASE_URL and TWYNE_JUDGE_MODEL are required for --judge openai-compatible",
63	    );
64	  return {
65	    label: `openai-compatible:${model}`,
66	    async complete(system, user, signal) {
67	      const response = await fetch(`${baseUrl}/chat/completions`, {
68	        method: "POST",
69	        headers: {
70	          "content-type": "application/json",
71	          ...(env.TWYNE_JUDGE_API_KEY
72	            ? { authorization: `Bearer ${env.TWYNE_JUDGE_API_KEY}` }
73	            : {}),
74	        },
75	        body: JSON.stringify({
76	          model,
77	          temperature: 0,
78	          messages: [
79	            { role: "system", content: system },
80	            { role: "user", content: user },
81	          ],
82	        }),
83	        signal,
84	      });
85	      if (!response.ok) {
86	        await response.body?.cancel();
87	        throw new Error(`Judge request failed (${response.status})`);
88	      }
89	      const json = (await response.json()) as {
90	        choices?: Array<{ message?: { content?: unknown } }>;
91	      };
92	      const content = json.choices?.[0]?.message?.content;
93	      if (typeof content !== "string")
94	        throw new Error("Judge response missing content");
95	      return content;
96	    },
97	  };
98	}
