100	async function labelled(
101	  judge: Judge,
102	  prompt: string,
103	  valid: Record<string, number>,
104	): Promise<Verdict> {
105	  const raw = await judge.complete(
106	    judgeSystemPrompt(Object.keys(valid)),
107	    prompt,
108	    AbortSignal.timeout(120_000),
109	  );
