134	/**
135	 * A graded read of one editor's note: the faithfulness and helpfulness
136	 * rubrics above pass nearly every competent note (1.00 and 0.98 on the first
137	 * Not Organic run), so they cannot rank one room against another. This asks
138	 * how much the note is worth to the writer, on anchored levels, and states
139	 * the expected distribution so "competent" lands in the middle.
140	 */
141	export async function judgeNoteValue(
142	  judge: Judge,
143	  input: { draft: string; persona: string; note: string; anchor?: string },
144	): Promise<{ score: number | null; label: string; explanation: string }> {
145	  const raw = await judge.complete(
146	    `You are a demanding senior editor grading another editor's note. Respond with a JSON object exactly: ` +
147	      `{"level": <integer 1-5>, "explanation": "<one sentence naming what the note gets right or wrong>"}. No other text.`,
148	    `Grade how much this note is worth to the writer of this draft.\n\n` +
149	      `1 = generic, wrong about the draft, or misreads the passage it quotes.\n` +
150	      `2 = about this draft but obvious or surface-level: restates the passage, praises or objects without a reason, or offers no usable next move.\n` +
151	      `3 = specific and correct, with a usable next move; what a competent editor writes.\n` +
152	      `4 = specific and correct, and names a non-obvious problem or strength with a concrete move that would change the next draft.\n` +
153	      `5 = the observation a top editor would lead with for this piece; it reframes the draft's main problem or protects its best move.\n\n` +
154	      `Most competent notes are a 3. Give 4 or 5 only when the note says something a careful writer would likely not have seen themselves. ` +
155	      `Check the note against the passage it quotes: a note that misdescribes it cannot score above 2.\n\n` +
156	      `Editor: ${input.persona}\n` +
157	      (input.anchor ? `Passage the note quotes:\n"${input.anchor}"\n\n` : "") +
158	      `Note:\n${input.note}\n\nDraft:\n${input.draft}`,
159	    AbortSignal.timeout(120_000),
160	  );
161	  const json = raw.match(/\{[\s\S]*\}/)?.[0] ?? "{}";
162	  try {
163	    const parsed = JSON.parse(json) as { level?: unknown; explanation?: unknown };
164	    const level = Number(parsed.level);
165	    if (!Number.isInteger(level) || level < 1 || level > 5) throw new Error("level");
166	    return {
167	      score: (level - 1) / 4,
168	      label: `level ${level}`,
169	      explanation: typeof parsed.explanation === "string" ? parsed.explanation : "",
170	    };
171	  } catch {
172	    return { score: null, label: "judge-error", explanation: raw.slice(0, 200) };
173	  }
174	}
