198	/**
199	 * How many planted weaknesses the rubric's feedback names. Returns the share
200	 * found, with the judge's list as the explanation.
201	 */
202	export async function judgeWeaknessRecall(
203	  judge: Judge,
204	  input: { draft: string; weaknesses: string[]; feedback: string },
205	): Promise<{ score: number; explanation: string }> {
206	  const numbered = input.weaknesses.map((w, i) => `${i + 1}. ${w}`).join("\n");
207	  const raw = await judge.complete(
208	    `You are a strict evaluator. Respond with a JSON object exactly: ` +
209	      `{"identified": [<numbers of the weaknesses the feedback identifies>], "explanation": "<one sentence>"}. No other text.`,
210	    `A draft was written with known weaknesses. Decide which of them the ` +
211	      `reviewers' feedback identifies, in substance and about this draft. ` +
212	      `General advice that happens to fit does not count.\n\n` +
213	      `Draft:\n${input.draft}\n\nKnown weaknesses:\n${numbered}\n\n` +
214	      `Reviewers' feedback:\n${input.feedback}`,
215	    AbortSignal.timeout(120_000),
216	  );
217	  const json = raw.match(/\{[\s\S]*\}/)?.[0] ?? "{}";
218	  let identified: number[] = [];
219	  let explanation = "";
220	  try {
221	    const parsed = JSON.parse(json) as {
222	      identified?: unknown;
223	      explanation?: unknown;
224	    };
225	    identified = Array.isArray(parsed.identified)
226	      ? parsed.identified
227	          .map(Number)
228	          .filter((n) => Number.isInteger(n) && n >= 1 && n <= input.weaknesses.length)
229	      : [];
230	    explanation = typeof parsed.explanation === "string" ? parsed.explanation : "";
231	  } catch {
232	    explanation = raw.slice(0, 200);
233	  }
234	  const found = new Set(identified);
235	  return {
236	    score: input.weaknesses.length ? found.size / input.weaknesses.length : 0,
237	    explanation:
238	      `${found.size}/${input.weaknesses.length} identified` +
239	      (explanation ? `: ${explanation}` : ""),
240	  };
241	}
