244	 * Run one judged metric. A judge that fails marks that metric "judge-error"
245	 * instead of failing the case: the app's answer is still worth scoring.
246	 */
247	export async function judged(task: () => Promise<Score>): Promise<Score> {
248	  try {
249	    return await task();
250	  } catch (error) {
251	    return {
252	      score: null,
253	      label: "judge-error",
254	      explanation: error instanceof Error ? error.message : String(error),
255	    };
256	  }
257	}
