259	/* ── Jev (System One) as an evaluator ─────────────────────────────── */
260	
261	/**
262	 * Jev answers typed questions with calibrated probabilities instead of
263	 * writing a verdict. It goes through the app's own System One path
264	 * (`LocalApp.judge`), so an eval asks it exactly as the editors' review gate
265	 * does: same transport, metering and limits.
266	 *
267	 * Each case batches its questions into one request; they run in parallel and
268	 * cannot see one another. A Score's expected value is scaled to 0..1 by its
269	 * top level; a Noul is already a probability.
270	 */
271	export type JevAsk = (request: {
272	  state: Record<string, string>;
273	  questions: Record<
274	    string,
275	    { type: "noul" | "choice" | "score"; instructions: string; criteria?: string[] }
276	  >;
277	}) => Promise<{ ok: boolean; answers?: Record<string, unknown>; error?: string }>;
278	
279	export interface JevVerdict {
280	  score: number | null;
281	  /** How concentrated Jev's distribution was (Score/Choice), or the Noul. */
282	  confidence: number | null;
283	  label?: string;
284	}
285	
286	export function readJevAnswer(answer: unknown): JevVerdict {
287	  const a = (answer ?? {}) as {
288	    type?: string;
289	    noul?: number;
290	    score?: number;
291	    confidence?: number;
292	    legend?: Record<string, string>;
293	    choice?: string;
294	  };
295	  if (a.type === "noul" && typeof a.noul === "number")
296	    return { score: a.noul, confidence: null, label: a.noul >= 0.5 ? "yes" : "no" };
297	  if (a.type === "score" && typeof a.score === "number") {
298	    const top = Math.max(1, Object.keys(a.legend ?? { 0: "", 1: "" }).length - 1);
299	    return {
300	      score: a.score / top,
301	      confidence: typeof a.confidence === "number" ? a.confidence : null,
302	      label: `level ${a.score.toFixed(1)}`,
303	    };
304	  }
305	  if (a.type === "choice" && typeof a.choice === "string")
306	    return {
307	      score: null,
308	      confidence: typeof a.confidence === "number" ? a.confidence : null,
309	      label: a.choice,
310	    };
311	  return { score: null, confidence: null };
312	}
313	
314	/** Clairic typed extraction through the app's own path (`LocalApp.extract`). */
315	export type ClairicAsk = (request: {
316	  state?: string;
317	  fields: Record<string, { type: string; instructions?: string; [key: string]: unknown }>;
318	  reference_date?: string;
319	}) => Promise<{ ok: boolean; answers?: Record<string, unknown>; error?: string }>;
320	
321	/** Run one batched Jev request; a failure marks every question jev-error. */
322	export async function askJev(
323	  jev: JevAsk,
324	  state: Record<string, string>,
325	  questions: Parameters<JevAsk>[0]["questions"],
326	): Promise<Record<string, Score>> {
327	  const ids = Object.keys(questions);
328	  try {
329	    const result = await jev({ state, questions });
330	    if (!result.ok || !result.answers)
331	      return Object.fromEntries(
332	        ids.map((id) => [id, { score: null, label: "jev-error", explanation: result.error ?? "no answer" }]),
333	      );
334	    return Object.fromEntries(
335	      ids.map((id) => {
336	        const v = readJevAnswer(result.answers?.[id]);
337	        return [
338	          id,
339	          {
340	            score: v.score,
341	            label: v.label ?? "jev-error",
342	            explanation:
343	              v.confidence !== null ? `Jev confidence ${v.confidence.toFixed(2)}` : "",
344	          },
345	        ];
346	      }),
347	    );
348	  } catch (error) {
349	    return Object.fromEntries(
350	      ids.map((id) => [
351	        id,
352	        { score: null, label: "jev-error", explanation: error instanceof Error ? error.message : String(error) },
353	      ]),
354	    );
355	  }
356	}
