162	const CONVEX_DIR = resolve(fileURLToPath(new URL("../../convex", import.meta.url)));
163	const ISSUER = "https://twyne.test";
164	
165	/**
166	 * Keys the Convex modules read for outside services. Bun loads `.env` files on
167	 * its own, so without this a mock run could quietly reach TypeSafe, PostHog or
168	 * a legacy provider. Each mode below re-adds only what it needs.
169	 */
170	const SERVICE_KEY =
171	  /^(NOTORGANIC_|TYPESAFE_|POSTHOG_|PUBLIC_POSTHOG_|RESEND_|ARIZE_|RESEARCH_|TINYFISH_|ANTHROPIC_|OPENAI_|RIVET_|PORTKEY_|VOICE_|FISH_|ELEVENLABS_|FAL_|GEMINI_|GOOGLE_|TWYNE_ALLOW_)/;
172	
173	function isolateServiceEnv(): void {
174	  for (const key of Object.keys(process.env)) {
175	    if (SERVICE_KEY.test(key)) delete process.env[key];
176	  }
177	}
178	
179	function convexModules(): Record<string, () => Promise<unknown>> {
180	  const files: string[] = [];
181	  const walk = (dir: string) => {
182	    for (const entry of readdirSync(dir, { withFileTypes: true })) {
183	      const path = join(dir, entry.name);
184	      if (entry.isDirectory()) walk(path);
185	      else if (
186	        /\.(ts|js)$/.test(entry.name) &&
187	        !entry.name.endsWith(".d.ts") &&
188	        !entry.name.endsWith(".test.ts")
189	      )
190	        files.push(path);
191	    }
192	  };
193	  walk(CONVEX_DIR);
194	  return Object.fromEntries(files.map((file) => [file, () => import(file)]));
195	}
196	
197	function required(
198	  env: Readonly<Record<string, string | undefined>>,
199	  key: string,
200	): string {
201	  const value = env[key]?.trim();
202	  if (!value) throw new Error(`${key} is required for this model mode`);
203	  return value;
204	}
205	
206	async function routeModel(
207	  mode: AppModelMode,
208	  env: Readonly<Record<string, string | undefined>>,
209	): Promise<{
210	  label: string;
211	  mock?: MockModelServer;
212	  did?: string;
213	  sessionVersion?: number;
214	}> {
215	  if (mode === "mock") {
216	    const mock = await startMockModel();
217	    process.env.RIVET_ENDPOINT = mock.url;
218	    process.env.RIVET_MODEL = "twyne-mock";
219	    return { label: "mock (scripted)", mock };
220	  }
221	  if (mode === "openai-compatible") {
222	    // The legacy route appends /v1 itself.
223	    process.env.RIVET_ENDPOINT = required(env, "TWYNE_APP_MODEL_BASE_URL")
224	      .replace(/\/+$/, "")
225	      .replace(/\/v1$/, "");
226	    process.env.RIVET_MODEL = required(env, "TWYNE_APP_MODEL");
227	    if (env.TWYNE_APP_MODEL_API_KEY)
228	      process.env.RIVET_TOKEN = env.TWYNE_APP_MODEL_API_KEY;
229	    return { label: `openai-compatible ${process.env.RIVET_MODEL}` };
230	  }
231	  for (const key of [
232	    "NOTORGANIC_ISSUER",
233	    "NOTORGANIC_ASSERTION_PRIVATE_KEY",
234	    "NOTORGANIC_ASSERTION_KEY_ID",
235	    "NOTORGANIC_AUDIENCE",
236	  ]) {
237	    if (env[key] !== undefined) process.env[key] = env[key];
238	  }
239	  required(env, "NOTORGANIC_ASSERTION_PRIVATE_KEY");
240	  process.env.NOTORGANIC_ENABLED = "true";
241	  process.env.NOTORGANIC_GENERATION_MAX_COST_MICROUSD =
242	    env.NOTORGANIC_GENERATION_MAX_COST_MICROUSD ??
243	    required(env, "TWYNE_EVAL_MAX_COST_MICROUSD");
244	  return {
245	    label: "notorganic",
246	    did: required(env, "TWYNE_EVAL_DID"),
247	    // The version Not Organic holds for the account; a DID without an account
248	    // row there is at 0, and a mismatch is refused as a revoked session.
249	    sessionVersion: Number(env.TWYNE_EVAL_SESSION_VERSION ?? 1),
250	  };
251	}
252	
253	function applyTracing(tracing: ArizeTracingConfig | null | undefined): void {
254	  if (!tracing) return;
255	  process.env.ARIZE_API_KEY = tracing.apiKey;
256	  process.env.ARIZE_SPACE_ID = tracing.spaceId;
257	  process.env.ARIZE_PROJECT_NAME = tracing.projectName;
258	  if (tracing.region) process.env.ARIZE_REGION = tracing.region;
259	  process.env.ARIZE_CAPTURE_CONTENT =
260	    tracing.captureContent === false ? "false" : "true";
261	}
