263	export async function startLocalApp(
264	  options: LocalAppOptions,
265	): Promise<LocalApp> {
266	  const env = options.env ?? { ...process.env };
267	  const before = { ...process.env };
268	  isolateServiceEnv();
269	  const routed = await routeModel(options.model, env);
270	  applyTracing(options.tracing);
271	  const systemOne =
272	    options.systemOne ??
273	    (options.model === "notorganic"
274	      ? "notorganic"
275	      : options.model === "mock"
276	        ? "mock"
277	        : env.TYPESAFE_API_KEY
278	          ? "direct"
279	          : "off");
280	  if (systemOne === "direct" && options.model === "notorganic") {
281	    // Not Organic wins over a direct key in the app's transport rules
282	    // (convex/lib/hostedTransports.ts). Its System One route can be down while
283	    // its inference is up, so for an eval the judgements are pinned to the
284	    // direct key and only the models go through Not Organic.
285	    process.env.TWYNE_EVAL_JUDGEMENT_TRANSPORT = "direct";
286	  }
287	  if (systemOne === "mock") {
288	    routed.mock ??= await startMockModel();
289	    process.env.TYPESAFE_API_KEY = "twyne-mock";
290	    process.env.TYPESAFE_BASE_URL = routed.mock.url;
291	  } else if (systemOne === "direct") {
292	    process.env.TYPESAFE_API_KEY = required(env, "TYPESAFE_API_KEY");
293	    if (env.TYPESAFE_BASE_URL) process.env.TYPESAFE_BASE_URL = env.TYPESAFE_BASE_URL;
294	  }
295	
296	  let keenable: KeenableBridge | undefined;
297	  const research: ResearchMode =
298	    options.research ??
299	    (options.model === "mock" ? "mock" : options.model === "notorganic" ? "notorganic" : "off");
300	  if (research === "mock") {
301	    routed.mock ??= await startMockModel();
302	    process.env.RESEARCH_PROVIDER = "custom";
303	    process.env.RESEARCH_SEARCH_URL = `${routed.mock.url}/v1/search`;
304	  } else if (research === "notorganic") {
305	    if (options.model !== "notorganic")
306	      throw new Error("--research notorganic needs --model notorganic");
307	    process.env.RESEARCH_PROVIDER = "notorganic";
308	    if (env.NOTORGANIC_SEARCH_MAX_COST_MICROUSD)
309	      process.env.NOTORGANIC_SEARCH_MAX_COST_MICROUSD = env.NOTORGANIC_SEARCH_MAX_COST_MICROUSD;
310	  } else if (research === "keenable") {
311	    keenable = await startKeenableBridge(required(env, "KEENABLE_API_KEY"));
312	    process.env.RESEARCH_PROVIDER = "custom";
313	    process.env.RESEARCH_SEARCH_URL = keenable.url;
314	  } else if (research === "custom") {
315	    process.env.RESEARCH_PROVIDER = "custom";
316	    process.env.RESEARCH_SEARCH_URL = required(env, "TWYNE_APP_SEARCH_URL");
317	    if (env.TWYNE_APP_SEARCH_API_KEY)
318	      process.env.RESEARCH_API_KEY = env.TWYNE_APP_SEARCH_API_KEY;
319	  }
320	
321	  const t = convexTest(schema, convexModules() as never);
322	  let writers = 0;
323	  let billingWriter: LocalWriter | undefined;
324	  let evaluator: LocalWriter | undefined;
325	
326	  const newWriter = async (name = "eval-writer"): Promise<LocalWriter> => {
327	    writers += 1;
328	    const subject = `${name}-${writers}`;
329	    const tokenIdentifier = `${ISSUER}|${subject}`;
330	    const writer = t.withIdentity({ tokenIdentifier, subject, issuer: ISSUER });
331	    if (routed.did) {
332	      const now = Date.now();
333	      await t.run(async (ctx) => {
334	        await ctx.db.insert("providerIdentities", {
335	          productSubject: subject,
336	          did: routed.did as string,
337	          verificationMethod: "notorganic_pkce",
338	          sessionVersion: routed.sessionVersion ?? 1,
339	          verifiedAt: now,
340	          createdAt: now,
341	          updatedAt: now,
342	        });
343	      });
344	    }
345	    const created = await writer.mutation(api.integrations.createToken, {
346	      name: subject,
347	    });
348	    return { token: created.token, tokenIdentifier };
349	  };
350	
351	  const appFetch = (async (input: RequestInfo | URL, init?: RequestInit) => {
352	    const url = new URL(
353	      input instanceof Request ? input.url : String(input),
354	      "http://local.twyne",
355	    );
356	    const request = input instanceof Request ? input : undefined;
357	    return t.fetch(`${url.pathname}${url.search}`, {
358	      method: init?.method ?? request?.method ?? "GET",
359	      headers: init?.headers ?? request?.headers,
360	      body: init?.body ?? (request ? await request.text() : undefined),
361	    });
362	  }) as typeof fetch;
363	
364	  const server: Server = createServer(async (req, res) => {
365	    try {
366	      let body = "";
367	      for await (const chunk of req) body += chunk;
368	      const headers = new Headers();
369	      for (const [key, value] of Object.entries(req.headers)) {
370	        if (typeof value === "string") headers.set(key, value);
371	      }
372	      const response = await t.fetch(req.url ?? "/", {
373	        method: req.method,
374	        headers,
375	        body: req.method === "GET" || req.method === "HEAD" ? undefined : body,
376	      });
377	      res.writeHead(response.status, Object.fromEntries(response.headers));
378	      res.end(Buffer.from(await response.arrayBuffer()));
379	    } catch (error) {
380	      res.writeHead(500, { "content-type": "application/json" });
381	      res.end(
382	        JSON.stringify({
383	          ok: false,
384	          error: error instanceof Error ? error.message : String(error),
385	        }),
386	      );
387	    }
388	  });
389	  await new Promise<void>((done) =>
390	    server.listen(options.port ?? 0, "127.0.0.1", () => done()),
391	  );
392	  const { port } = server.address() as { port: number };
393	  // This is a local deployment; the direct transports only run on one.
394	  process.env.CONVEX_CLOUD_URL = `http://127.0.0.1:${port}`;
395	
396	  return {
397	    url: `http://127.0.0.1:${port}`,
398	    modelLabel: `${routed.label}; System One ${systemOne}; research ${research}`,
399	    mock: routed.mock,
400	    newWriter,
401	    fetch: appFetch,
402	    judge: async (request) => {
403	      evaluator ??= await newWriter("evaluator");
404	      return (await t.action(internal.systemOne.askAs, {
405	        ownerId: evaluator.tokenIdentifier,
406	        ...request,
407	      })) as JudgementAnswer;
408	    },
409	    extract: async (request) => {
410	      evaluator ??= await newWriter("evaluator");
411	      return (await t.action(internal.extraction.extractAs, {
412	        ownerId: evaluator.tokenIdentifier,
413	        ...request,
414	      } as never)) as ExtractionAnswer;
415	    },
416	    billed: async (from, to) => {
417	      if (!routed.did) return null;
418	      billingWriter ??= await newWriter("billing");
419	      try {
420	        return (await t
421	          .withIdentity({
422	            tokenIdentifier: billingWriter.tokenIdentifier,
423	            subject: billingWriter.tokenIdentifier.slice(ISSUER.length + 1),
424	            issuer: ISSUER,
425	          })
426	          .action(api.providerIdentity.getHostedUsage, { from, to })) as HostedBilling;
427	      } catch {
428	        return null;
429	      }
430	    },
431	    usage: () =>
432	      t.run(async (ctx) => {
433	        const totals: UsageTotals = {
434	          calls: 0,
435	          costMicrousd: 0,
436	          unpriced: 0,
437	          inputTokens: 0,
438	          outputTokens: 0,
439	        };
440	        for (const event of await ctx.db.query("aiUsageEvents").collect()) {
441	          totals.calls += 1;
442	          if (typeof event.costMicrousd === "number")
443	            totals.costMicrousd += event.costMicrousd;
444	          else totals.unpriced += 1;
445	          totals.inputTokens += event.inputTokens ?? 0;
446	          totals.outputTokens += event.outputTokens ?? 0;
447	        }
448	        return totals;
449	      }),
450	    close: async () => {
451	      await new Promise<void>((done) => server.close(() => done()));
452	      await routed.mock?.close();
453	      await keenable?.close();
454	      // Leave the process as it was found; tests share one.
455	      for (const key of Object.keys(process.env))
456	        if (!(key in before)) delete process.env[key];
457	      Object.assign(process.env, before);
458	    },
459	  };
460	}
461	
462	if (import.meta.main) {
463	  const args = process.argv.slice(2);
464	  const flag = (name: string) => {
465	    const index = args.indexOf(name);
466	    return index >= 0 ? args[index + 1] : undefined;
467	  };
468	  const model = (flag("--model") ?? "mock") as AppModelMode;
469	  if (!["mock", "openai-compatible", "notorganic"].includes(model)) {
470	    console.error("--model must be mock, openai-compatible or notorganic");
471	    process.exit(2);
472	  }
473	  const app = await startLocalApp({
474	    model,
475	    port: Number(flag("--port") ?? 0),
476	  });
477	  const writer = await app.newWriter("local");
478	  console.log(`Twyne is running in-process (${app.modelLabel}).\n`);
479	  console.log(`export TWYNE_API_URL=${app.url}`);
480	  console.log(`export TWYNE_ACCESS_TOKEN=${writer.token}\n`);
481	  console.log("Ctrl-C to stop.");
482	  const stop = async () => {
483	    await app.close();
484	    process.exit(0);
485	  };
486	  process.on("SIGINT", stop);
487	  process.on("SIGTERM", stop);
488	}
