49	function notesOf(raw: unknown): EditorNote[] {
50	  const notes = (raw as { notes?: unknown })?.notes;
51	  return Array.isArray(notes) ? (notes as EditorNote[]) : [];
52	}
53	
54	function anchorsOf(note: EditorNote): string[] {
55	  if (note.anchors?.length) return note.anchors;
56	  return note.anchor ? [note.anchor] : [];
57	}
58	
59	function covers(draft: string, note: EditorNote, plant: Plant): boolean {
60	  return (
61	    anchorsOf(note).some((anchor) =>
62	      spansOverlap(draft, anchor, plant.passage),
63	    ) || sharesRun(note.text, plant.passage, 5)
64	  );
65	}
