67	export function renderNotes(notes: EditorNote[]): string {
68	  return notes
69	    .map((note) => {
70	      const head = `[${note.personaName ?? note.personaId}] (${note.type ?? "note"}, ${note.provider ?? "?"})`;
71	      const anchor = note.anchor ? `\n  > ${note.anchor}` : "";
72	      return `${head} ${note.text}${anchor}`;
73	    })
74	    .join("\n\n");
75	}
