90	  async score({ judge, jev }, testCase, raw) {
91	    const draft = testCase.draftText;
92	    const notes = notesOf(raw);
93	    const written = notes.filter((note) => note.text?.trim());
94	    const anchors = notes.flatMap(anchorsOf);
95	    const verbatim = anchors.filter((anchor) => contains(draft, anchor));
96	    const visible = testCase.plants.filter((plant) =>
97	      visibleToEditors(draft, plant.passage),
98	    );
99	    const coveredBy = (plant: Plant) =>
100	      notes.filter((note) => covers(draft, note, plant));
101	    const missed = testCase.plants.filter((p) => coveredBy(p).length === 0);
102	    const expectedHit = testCase.plants.filter((plant) =>
103	      coveredBy(plant).some((note) =>
104	        plant.expectedEditors.includes(note.personaId),
105	      ),
106	    );
107	    const primary = notes.map((note) => note.anchor).filter(Boolean) as string[];
108	
109	    const scores: Record<string, Score> = {
110	      notes_complete: {
111	        score: ratio(written.length, 5),
112	        explanation: `${written.length} of 5 editors wrote a note`,
113	      },
114	      hosted: {
115	        score:
116	          ratio(
117	            notes.filter((note) => note.provider && note.provider !== "local").length,
118	            notes.length,
119	          ) ?? 0,
120	        explanation: `providers: ${[...new Set(notes.map((n) => n.provider))].join(", ")}`,
121	      },
122	      anchored: {
123	        score: ratio(notes.filter((note) => note.anchor).length, notes.length) ?? 0,
124	        explanation: "share of notes pinned to a passage by quote_passage",
125	      },
126	      anchor_verbatim: {
127	        // No anchors at all is a room that pinned nothing, not a missing check.
128	        score: ratio(verbatim.length, anchors.length) ?? 0,
129	        explanation: `${verbatim.length}/${anchors.length} anchors appear verbatim in the draft`,
130	      },
131	      plant_coverage: {
132	        score: ratio(testCase.plants.length - missed.length, testCase.plants.length),
133	        explanation: missed.length
134	          ? `missed: ${missed.map((p) => `${p.id} (${p.kind})`).join(", ")}`
135	          : "every planted feature was noticed",
136	      },
137	      plant_coverage_visible: {
138	        score:
139	          ratio(
140	            visible.filter((plant) => coveredBy(plant).length > 0).length,
141	            visible.length,
142	          ) ?? 1,
143	        explanation: `${testCase.plants.length - visible.length} plant(s) sit in the middle the editors' 4,500-character clamp drops`,
144	      },
145	      expected_editor: {
146	        score: ratio(expectedHit.length, testCase.plants.length),
147	        explanation: "planted features noticed by an editor whose remit covers them",
148	      },
149	      anchor_spread: {
150	        score: ratio(new Set(primary.map(fold)).size, primary.length) ?? 0,
151	        explanation: "distinct passages chosen across the room",
152	      },
153	      voice_distinctness: {
154	        score: distinctness(written.map((note) => note.text)) ?? 0,
155	        explanation: "1 minus mean pairwise trigram overlap between notes",
156	      },
157	    };
158	
159	    if (judge) {
160	      const verdicts = await Promise.all(
161	        written.map(async (note) => ({
162	          note,
163	          faithful: await judgeFaithfulness(judge, draft, note.text),
164	          helpful: await judgeHelpfulness(
165	            judge,
166	            `${note.personaName ?? note.personaId} (${note.personaId})`,
167	            draft,
168	            note.text,
169	          ),
170	          value: await judgeNoteValue(judge, {
171	            draft,
172	            persona: `${note.personaName ?? note.personaId} (${note.personaId})`,
173	            note: note.text,
174	            anchor: note.anchor,
175	          }),
176	        })),
177	      ).then(
178	        (value) => ({ ok: true as const, value }),
179	        (error: unknown) => ({ ok: false as const, error }),
180	      );
181	      const perNote = (pick: "faithful" | "helpful" | "value"): Score =>
182	        verdicts.ok
183	          ? {
184	              score: mean(verdicts.value.map((v) => v[pick].score)) ?? 0,
185	              explanation:
186	                verdicts.value
187	                  .map((v) => `${v.note.personaId}: ${v[pick].label}`)
188	                  .join("; ") || "no notes to judge",
189	            }
190	          : {
191	              score: null,
192	              label: "judge-error",
193	              explanation:
194	                verdicts.error instanceof Error
195	                  ? verdicts.error.message
196	                  : String(verdicts.error),
197	            };
198	      scores.faithfulness = await judged(async () => perNote("faithful"));
199	      scores.helpfulness = await judged(async () => perNote("helpful"));
200	      // The discriminating one: anchored 1-5 levels, scaled to 0-1.
201	      scores.note_value = await judged(async () => perNote("value"));
202	    }
203	    if (jev && written.length) {
204	      // One batched Jev request per note, all notes in parallel.
205	      const perNote = await Promise.all(
206	        written.map((note) =>
207	          askJev(
208	            jev,
209	            { draft, note: note.text, anchor: note.anchor ?? "(no passage quoted)" },
210	            JEV_NOTE_QUESTIONS,
211	          ),
212	        ),
213	      );
214	      for (const key of Object.keys(JEV_NOTE_QUESTIONS)) {
215	        const values = perNote.map((answers) => answers[key]?.score ?? null);
216	        const failed = perNote.filter((answers) => answers[key]?.label === "jev-error").length;
217	        scores[key] = {
218	          score: failed === perNote.length ? null : mean(values),
219	          label: failed === perNote.length ? "jev-error" : undefined,
220	          explanation: written
221	            .map((note, i) => `${note.personaId}: ${perNote[i][key]?.label ?? "?"}`)
222	            .join("; "),
223	        };
224	      }
225	    }
226	    return scores;
227	  },
