1	/**
2	 * Auto-research, the Apparatus' background pass, in two suites.
3	 *
4	 * `research-targets` asks whether the right passages were flagged. Each draft
5	 * in `cases/research.jsonl` names the claims that need a source (`mustFlag`)
6	 * and the passages that must be left alone: opinion, experience, invented
7	 * story, common knowledge (`mustNotFlag`). Every draft runs through both
8	 * strategies the product has:
9	 *
10	 *   hosted  what a writer on Twyne's hosted service gets today: sentences
11	 *           the text rules propose, confirmed by System One
12	 *   model   what a writer with their own model gets: the research-extract
13	 *           prompts, here on the hosted model
14	 *
15	 * so the scores compare the two directly.
16	 *
17	 * `research-sources` takes each gold claim as a target (its passage, kind
18	 * and a librarian's query) and asks whether search returns a source that
19	 * settles it. Deterministic checks look for the expected source among the
20	 * results; the judge, when enabled, reads the returned snippets against the
21	 * fact.
22	 */
23	import { askJev, judged, type ClairicAsk, type Judge, type JevAsk } from "../judges";
24	import { contains, fold, ratio, type Score } from "../scoring";
25	import { readJsonl } from "./load";
26	import type { ProjectBrief, Suite } from "./types";
27	
28	type TargetKind = "quote" | "work" | "person" | "statistic" | "claim" | "event";
29	type Strategy = "hosted" | "model";
30	
31	interface GoldClaim {
32	  id: string;
33	  kind: TargetKind;
34	  passage: string;
35	  needles: string[];
36	  fact: string;
37	  query: string;
38	  sources: string[];
39	  plantedError?: boolean;
40	}
41	
42	interface Restraint {
43	  id: string;
44	  why: string;
45	  passage: string;
46	  needles: string[];
47	}
48	
49	export interface ResearchDraft {
50	  case_id: string;
51	  genre: string;
52	  mode: "fiction" | "nonfiction" | "general";
53	  brief: ProjectBrief;
54	  draftText: string;
55	  mustFlag: GoldClaim[];
56	  mustNotFlag: Restraint[];
57	}
58	
59	interface Target {
60	  kind: TargetKind;
61	  anchor: string;
62	  query: string;
63	  reason?: string;
64	  importance?: number;
65	}
66	
67	interface TargetsResult {
68	  strategy?: Strategy;
69	  provider?: string;
70	  mode?: string;
71	  targets?: Target[];
72	  candidates?: Array<{ kind: TargetKind; anchor: string }>;
73	}
74	
75	interface Source {
76	  title: string;
77	  url: string;
78	  snippet?: string;
79	  publisher?: string;
