89	const CORPUS = "app/cases/research.jsonl";
90	
91	/* ── Matching ───────────────────────────────────────────────────── */
92	
93	/**
94	 * Does `target` cover this passage? Either its anchor overlaps the passage in
95	 * the draft, or its anchor and query together carry every needle.
96	 */
97	function covers(
98	  target: Target,
99	  passage: string,
100	  needles: string[],
101	): boolean {
102	  const anchor = fold(target.anchor).toLowerCase();
103	  const want = fold(passage).toLowerCase();
104	  if (anchor.length >= 12 && (want.includes(anchor) || anchor.includes(want)))
105	    return true;
106	  const haystack = `${anchor} ${fold(target.query).toLowerCase()}`;
107	  return (
108	    needles.length > 0 &&
109	    needles.every((n) => haystack.includes(n.toLowerCase()))
110	  );
111	}
112	
113	function targetsOf(raw: unknown): Target[] {
114	  const list = (raw as TargetsResult | null)?.targets;
115	  return Array.isArray(list) ? list : [];
116	}
117	
118	/* ── research-targets ───────────────────────────────────────────── */
119	
120	export interface ResearchTargetCase extends ResearchDraft {
121	  /** `<draft case_id>:<strategy>`. */
122	  case_id: string;
123	  draft_id: string;
124	  strategy: Strategy;
125	}
126	
127	function renderTargets(result: TargetsResult): string {
128	  const targets = targetsOf(result);
129	  if (!targets.length) return "(no targets)";
130	  return targets
131	    .map(
132	      (t) =>
133	        `[${t.kind}] ${t.importance ?? "?"} → ${t.query}\n  > ${t.anchor}`,
134	    )
135	    .join("\n");
136	}
137	
138	function loadDrafts(): ResearchDraft[] {
139	  return readJsonl<ResearchDraft>(CORPUS);
140	}
