142	export const researchTargetsSuite: Suite<ResearchTargetCase> = {
143	  name: "research-targets",
144	  surface: "integration research.targets",
145	  load: () =>
146	    loadDrafts().flatMap((draft) =>
147	      (["hosted", "model"] as const).map((strategy) => ({
148	        ...draft,
149	        case_id: `${draft.case_id}:${strategy}`,
150	        draft_id: draft.case_id,
151	        strategy,
152	      })),
153	    ),
