166	  async score(_ctx, testCase, raw) {
167	    const draft = testCase.draftText;
168	    const targets = targetsOf(raw);
169	    const result = raw as TargetsResult;
170	    const found = testCase.mustFlag.filter((claim) =>
171	      targets.some((t) => covers(t, claim.passage, claim.needles)),
172	    );
173	    const restrained = testCase.mustNotFlag.filter(
174	      (bait) => !targets.some((t) => covers(t, bait.passage, bait.needles)),
175	    );
176	    const matchedTargets = targets.filter((t) =>
177	      testCase.mustFlag.some((claim) => covers(t, claim.passage, claim.needles)),
178	    );
179	    const kindRight = testCase.mustFlag.filter((claim) => {
180	      const hit = targets.find((t) => covers(t, claim.passage, claim.needles));
181	      return hit?.kind === claim.kind;
182	    });
183	    const planted = testCase.mustFlag.filter((claim) => claim.plantedError);
184	    const anchorsVerbatim = targets.filter((t) => contains(draft, t.anchor));
185	
186	    // The search query a target carries is what the next agent searches
187	    // with: does it still name the claim?
188	    const queryCarries = found.filter((claim) => {
189	      const hit = targets.find((t) => covers(t, claim.passage, claim.needles));
190	      const q = fold(hit?.query ?? "").toLowerCase();
191	      return claim.needles.some((n) => q.includes(n.toLowerCase()));
192	    });
193	
194	    const missed = testCase.mustFlag.filter((c) => !found.includes(c));
195	    const overreach = testCase.mustNotFlag.filter((b) => !restrained.includes(b));
196	    const scores: Record<string, Score> = {
197	      recall: {
198	        score: ratio(found.length, testCase.mustFlag.length) ?? 1,
199	        explanation: missed.length
200	          ? `missed: ${missed.map((c) => `${c.id} (${c.kind})`).join(", ")}`
201	          : "every claim that needs a source was flagged",
202	      },
203	      restraint: {
204	        score: ratio(restrained.length, testCase.mustNotFlag.length) ?? 1,
205	        explanation: overreach.length
206	          ? `flagged anyway: ${overreach.map((b) => `${b.id} (${b.why})`).join(", ")}`
207	          : "left opinion, experience and invention alone",
208	      },
209	      precision: {
210	        // Targets that match a gold claim, of all targets returned. Unlisted
211	        // but legitimate claims count against it, so read it with restraint.
212	        score: targets.length ? matchedTargets.length / targets.length : 1,
213	        explanation: `${matchedTargets.length}/${targets.length} targets match a listed claim`,
214	      },
215	      kind_accuracy: {
216	        score: ratio(kindRight.length, found.length) ?? 1,
217	        explanation: "found claims filed under the right kind",
218	      },
219	      query_carries_claim: {
220	        score: ratio(queryCarries.length, found.length) ?? 1,
221	        explanation: "found claims whose search query still names the claim",
222	      },
223	      anchors_verbatim: {
224	        score: ratio(anchorsVerbatim.length, targets.length) ?? 1,
225	        explanation: `${anchorsVerbatim.length}/${targets.length} anchors quote the draft exactly`,
226	      },
227	      mode: {
228	        score: result.mode === testCase.mode ? 1 : 0,
229	        label: result.mode ?? "?",
230	        explanation: `expected ${testCase.mode}`,
231	      },
232	    };
233	    if (planted.length) {
234	      const caught = planted.filter((c) => found.includes(c));
235	      scores.planted_error_flagged = {
236	        score: caught.length / planted.length,
237	        explanation: `${caught.length}/${planted.length} planted errors flagged for checking`,
238	      };
239	    }
240	    return scores;
241	  },
242	
243	  example: (testCase) => ({
244	    case_id: testCase.case_id,
245	    draft_id: testCase.draft_id,
246	    strategy: testCase.strategy,
247	    genre: testCase.genre,
248	    mode: testCase.mode,
249	    draftText: testCase.draftText,
250	    mustFlag: JSON.stringify(testCase.mustFlag),
251	    mustNotFlag: JSON.stringify(testCase.mustNotFlag),
252	  }),
253	};
