429	  },
430	
431	  async score({ judge, jev, extract }, testCase, raw) {
432	    const sources = sourcesOf(raw);
433	    const result = raw as SourcesResult;
434	    const firstExpected = sources.findIndex((s) => expected(s, testCase.sources));
435	    const scores: Record<string, Score> = {
436	      found: {
437	        score: sources.length ? 1 : 0,
438	        explanation: `${sources.length} source(s) from ${result.provider ?? "?"}`,
439	      },
440	      expected_source: {
441	        // An authority the corpus names as settling the fact, anywhere in
442	        // the results.
443	        score: firstExpected >= 0 ? 1 : 0,
444	        explanation:
445	          firstExpected >= 0
446	            ? `${sources[firstExpected].url} at rank ${firstExpected + 1}`
447	            : `none of ${testCase.sources.join(", ")}`,
448	      },
449	      expected_source_rank: {
450	        // Reciprocal rank: 1 at the top, 0.5 second, 0 when absent.
451	        score: firstExpected >= 0 ? 1 / (firstExpected + 1) : 0,
452	        explanation: firstExpected >= 0 ? `rank ${firstExpected + 1}` : "absent",
453	      },
454	      live: {
455	        score: result.provider && result.provider !== "local" ? 1 : 0,
456	        label: result.provider ?? "?",
457	        explanation: "results came from a live provider, not the placeholder",
458	      },
459	    };
460	    if (judge) {
461	      scores.settles = await judged(() => judgeSettles(judge, testCase, sources));
462	    }
463	    if (jev) scores.jev_settles = await jevSettles(jev, testCase, sources);
464	    if (extract) scores.clairic_fact = await clairicFact(extract, testCase, sources);
465	    return scores;
466	  },
467	
468	  example: (testCase) => ({
469	    case_id: testCase.case_id,
470	    draft_id: testCase.draft_id,
471	    kind: testCase.kind,
472	    passage: testCase.passage,
473	    fact: testCase.fact,
474	    query: testCase.query,
475	    sources: JSON.stringify(testCase.sources),
476	    plantedError: testCase.plantedError === true,
477	  }),
478	};
