1	/**
2	 * The rubric, graded through `twyne_grade_draft` on strong/weak pairs.
3	 *
4	 * Each topic has a strong draft and a fluent but padded, hedging, generic
5	 * one under the same brief. The rubric earns its keep only if it ranks the
6	 * pair correctly, so ordering is scored per pair and attached to both cases.
7	 * The judge, when enabled, checks whether the feedback on a weak draft names
8	 * the weaknesses that were planted in it.
9	 */
10	import { judged, judgeFaithfulness, judgeWeaknessRecall } from "../judges";
11	import { pass, ratio, type Score } from "../scoring";
12	import { readJsonl } from "./load";
13	import type { ProjectBrief, ScoredCase, Suite } from "./types";
14	
15	export interface RubricCase {
16	  case_id: string;
17	  pair_id: string;
18	  quality: "strong" | "weak";
19	  brief: ProjectBrief;
20	  draftText: string;
21	  weaknesses?: string[];
22	}
23	
24	interface Judgement {
25	  score: number;
26	  rationale: string;
27	  provider?: string;
28	}
29	
30	interface RubricGrade {
31	  /** Persona judges that returned nothing usable, even after a retry. */
32	  unjudged?: string[];
33	  grade?: string;
34	  combined?: number;
35	  judgeMean?: number;
36	  minJudge?: number;
37	  staticTotal?: number;
38	  judges?: Array<Judgement & { personaId: string }>;
39	  sufficiency?: Judgement;
40	  evidence?: Judgement;
41	  integrity?: Judgement;
42	  targetFit?: Judgement;
43	  review?: { text: string; provider?: string } | null;
44	}
45	
46	const DIMENSIONS = ["sufficiency", "evidence", "integrity", "targetFit"] as const;
47	
48	function gradeOf(raw: unknown): RubricGrade {
49	  return (raw ?? {}) as RubricGrade;
50	}
51	
52	function validJudgement(j: Judgement | undefined): boolean {
53	  return (
54	    !!j &&
55	    Number.isInteger(j.score) &&
56	    j.score >= 1 &&
57	    j.score <= 10 &&
58	    typeof j.rationale === "string" &&
59	    j.rationale.trim().length > 0
60	  );
61	}
62	
63	function feedbackText(grade: RubricGrade): string {
64	  return [
65	    ...(grade.judges ?? []).map((j) => `${j.personaId}: ${j.rationale}`),
66	    ...DIMENSIONS.map((d) => `${d}: ${grade[d]?.rationale ?? ""}`),
67	    grade.review?.text ? `Review: ${grade.review.text}` : "",
68	  ]
69	    .filter(Boolean)
70	    .join("\n");
71	}
72	
73	export function renderGrade(grade: RubricGrade): string {
74	  const judges = (grade.judges ?? [])
75	    .map((j) => `  ${j.personaId.padEnd(8)} ${j.score}  ${j.rationale}`)
76	    .join("\n");
77	  const dims = DIMENSIONS.map(
78	    (d) => `  ${d.padEnd(11)} ${grade[d]?.score ?? "-"}  ${grade[d]?.rationale ?? ""}`,
79	  ).join("\n");
80	  return (
81	    `Grade ${grade.grade ?? "?"} (combined ${grade.combined ?? "?"}, judges ${grade.judgeMean ?? "?"}, static ${grade.staticTotal ?? "?"})\n` +
82	    `${judges}\n${dims}` +
83	    (grade.review?.text ? `\n\n${grade.review.text}` : "")
84	  );
85	}
86	
87	export const rubricSuite: Suite<RubricCase> = {
88	  name: "rubric",
89	  surface: "MCP twyne_grade_draft",
90	  load: () => readJsonl<RubricCase>("app/cases/rubric.jsonl"),
91	
92	  async run({ mcp }, testCase) {
93	    const raw = await mcp.call("twyne_grade_draft", {
94	      draftText: testCase.draftText,
95	      brief: testCase.brief,
96	    });
97	    return { raw, output: renderGrade(gradeOf(raw)) };
98	  },
99	
100	  async score({ judge }, testCase, raw) {
101	    const grade = gradeOf(raw);
102	    const judges = grade.judges ?? [];
103	    const all: Array<Judgement | undefined> = [
104	      ...judges,
105	      ...DIMENSIONS.map((d) => grade[d]),
106	    ];
107	    const invalid = all.filter((j) => !validJudgement(j)).length;
108	    const scores: Record<string, Score> = {
109	      contract: pass(
110	        typeof grade.grade === "string" &&
111	          typeof grade.combined === "number" &&
112	          judges.length + (grade.unjudged?.length ?? 0) === 5 &&
113	          invalid === 0,
114	        invalid ? `${invalid} judgement(s) missing or out of range` : undefined,
115	      ),
116	      // Every editor actually read and scored the draft; a gap is reported
117	      // by the app rather than papered over with a heuristic.
118	      judged: {
119	        score: judges.length / 5,
120	        explanation: grade.unjudged?.length
121	          ? `unjudged: ${grade.unjudged.join(", ")}`
122	          : "all five editors scored the draft",
123	      },
124	      hosted: {
125	        score: ratio(
126	          all.filter((j) => j?.provider && j.provider !== "local").length,
127	          all.length,
128	        ),
129	        explanation: "judgements answered by the hosted model, not the local fallback",
130	      },
131	      review_present: pass(!!grade.review?.text?.trim()),
132	    };
133	
134	    if (judge) {
135	      const review = grade.review?.text?.trim();
136	      scores.review_grounded = await judged(async () => {
137	        if (!review) return { score: 0, label: "absent", explanation: "no review" };
138	        const grounded = await judgeFaithfulness(judge, testCase.draftText, review);
139	        return {
140	          score: grounded.score ?? 0,
141	          label: grounded.label,
142	          explanation: grounded.explanation,
143	        };
144	      });
145	      if (testCase.quality === "weak" && testCase.weaknesses?.length) {
146	        const weaknesses = testCase.weaknesses;
147	        scores.weakness_recall = await judged(() =>
148	          judgeWeaknessRecall(judge, {
149	            draft: testCase.draftText,
150	            weaknesses,
151	            feedback: feedbackText(grade),
152	          }),
153	        );
154	      }
155	    }
156	    return scores;
157	  },
158	
159	  scoreAll(results: Array<ScoredCase<RubricCase>>) {
160	    const pairs = new Map<string, Partial<Record<"strong" | "weak", ScoredCase<RubricCase>>>>();
161	    for (const result of results) {
162	      const pair = pairs.get(result.case.pair_id) ?? {};
163	      pair[result.case.quality] = result;
164	      pairs.set(result.case.pair_id, pair);
165	    }
166	    for (const { strong, weak } of pairs.values()) {
167	      if (!strong || !weak) continue;
168	      const a = gradeOf(strong.raw);
169	      const b = gradeOf(weak.raw);
170	      const order = (x?: number, y?: number): Score =>
171	        typeof x === "number" && typeof y === "number"
172	          ? {
173	              score: x > y ? 1 : x === y ? 0.5 : 0,
174	              label: x > y ? "ordered" : x === y ? "tied" : "inverted",
175	              explanation: `strong ${x} vs weak ${y}`,
176	            }
177	          : { score: null, explanation: "a grade is missing" };
178	      const scores: Record<string, Score> = {
179	        pair_order: order(a.combined, b.combined),
180	        evidence_order: order(a.evidence?.score, b.evidence?.score),
181	        integrity_order: order(a.integrity?.score, b.integrity?.score),
182	        sufficiency_order: order(a.sufficiency?.score, b.sufficiency?.score),
183	      };
184	      Object.assign(strong.scores, scores);
185	      Object.assign(weak.scores, scores);
186	    }
187	  },
188	
189	  example: (testCase) => ({
190	    case_id: testCase.case_id,
191	    pair_id: testCase.pair_id,
192	    quality: testCase.quality,
193	    draftText: testCase.draftText,
194	    brief: JSON.stringify(testCase.brief),
195	    weaknesses: JSON.stringify(testCase.weaknesses ?? []),
196	  }),
197	};
