1	/**
2	 * Suggested rewrites through `twyne_suggest_rewrite`.
3	 *
4	 * A rewrite has to change the passage, keep the facts that make it the
5	 * writer's, and respect the size rule the prompt states (one sentence, or no
6	 * longer than the original paragraph). The judge, when enabled, decides
7	 * whether the stated problem was actually fixed.
8	 */
9	import { judged, judgeRewrite } from "../judges";
10	import { jaccard, keepsFact, pass, ratio, words, type Score } from "../scoring";
11	import { readJsonl } from "./load";
12	import type { ProjectBrief, Suite } from "./types";
13	
14	export interface RewriteCase {
15	  case_id: string;
16	  personaId: string;
17	  level: "sentence" | "paragraph";
18	  brief: ProjectBrief;
19	  draftText: string;
20	  original: string;
21	  problem: string;
22	  mustPreserve: string[];
23	}
24	
25	interface RewriteResult {
26	  replacement?: string;
27	  rationale?: string;
28	  provider?: string;
29	}
30	
31	function sentenceCount(text: string): number {
32	  return (text.match(/[.!?]+(\s|$)/g) ?? []).length || 1;
33	}
34	
35	export const rewriteSuite: Suite<RewriteCase> = {
36	  name: "rewrite",
37	  surface: "MCP twyne_suggest_rewrite",
38	  load: () => readJsonl<RewriteCase>("app/cases/rewrite.jsonl"),
39	
40	  async run({ mcp }, testCase) {
41	    const raw = await mcp.call("twyne_suggest_rewrite", {
42	      personaId: testCase.personaId,
43	      draftText: testCase.draftText,
44	      original: testCase.original,
45	      level: testCase.level,
46	      brief: testCase.brief,
47	    });
48	    const result = raw as RewriteResult;
49	    return {
50	      raw,
51	      output: `${result.replacement ?? ""}\n\n(${testCase.personaId}, ${result.provider ?? "?"}) ${result.rationale ?? ""}`,
52	    };
53	  },
54	
55	  async score({ judge }, testCase, raw) {
56	    const result = raw as RewriteResult;
57	    const replacement = result.replacement?.trim() ?? "";
58	    const kept = testCase.mustPreserve.filter((fact) => keepsFact(replacement, fact));
59	    const originalWords = words(testCase.original).length;
60	    const replacementWords = words(replacement).length;
61	    const lengthOk =
62	      testCase.level === "sentence"
63	        ? sentenceCount(replacement) <= 1 &&
64	          replacementWords <= Math.ceil(originalWords * 1.5) + 5
65	        : replacementWords <= Math.ceil(originalWords * 1.15);
66	    const scores: Record<string, Score> = {
67	      contract: pass(
68	        replacement.length > 0 && replacement !== testCase.original.trim(),
69	        replacement ? undefined : "no replacement returned",
70	      ),
71	      hosted: pass(!!result.provider && result.provider !== "local", result.provider),
72	      preserves_facts: {
73	        score: ratio(kept.length, testCase.mustPreserve.length) ?? 1,
74	        explanation:
75	          `${kept.length}/${testCase.mustPreserve.length} kept` +
76	          (kept.length < testCase.mustPreserve.length
77	            ? `; dropped ${testCase.mustPreserve.filter((fact) => !kept.includes(fact)).join(", ")}`
78	            : ""),
79	      },
80	      size_rule: pass(
81	        lengthOk,
82	        `${replacementWords} words vs ${originalWords} in the original (${testCase.level})`,
83	      ),
84	      changed: pass(
85	        jaccard(testCase.original, replacement) < 0.85,
86	        "the replacement is not a near-copy of the original",
87	      ),
88	    };
89	    if (judge) {
90	      scores.improves = await judged(async () => {
91	        if (!replacement)
92	          return { score: 0, label: "absent", explanation: "no replacement" };
93	        const verdict = await judgeRewrite(judge, {
94	          draft: testCase.draftText,
95	          original: testCase.original,
96	          problem: testCase.problem,
97	          replacement,
98	        });
99	        return {
100	          score: verdict.score ?? 0,
101	          label: verdict.label,
102	          explanation: verdict.explanation,
103	        };
104	      });
105	    }
106	    return scores;
107	  },
108	
109	  example: (testCase) => ({
110	    case_id: testCase.case_id,
111	    personaId: testCase.personaId,
112	    level: testCase.level,
113	    draftText: testCase.draftText,
114	    original: testCase.original,
115	    problem: testCase.problem,
116	    mustPreserve: JSON.stringify(testCase.mustPreserve),
117	    brief: JSON.stringify(testCase.brief),
118	  }),
119	};
