1	/**
2	 * The dossier check through the `twyne` CLI (`twyne dossier check --json`).
3	 *
4	 * This is the one suite that goes through the CLI rather than MCP, which
5	 * keeps the CLI's argument handling and JSON output under the same eval as
6	 * the model behind it. Each case drifts from its brief in planted ways; the
7	 * check should flag the brief fields the draft has outgrown or contradicted.
8	 */
9	import { pass, ratio, type Score } from "../scoring";
10	import { runCliJson } from "../drivers";
11	import { readJsonl } from "./load";
12	import type { ProjectBrief, Suite } from "./types";
13	
14	const FIELDS = [
15	  "workingTitle",
16	  "format",
17	  "audience",
18	  "goal",
19	  "tone",
20	  "constraints",
21	  "successSignal",
22	] as const;
23	
24	export interface DossierCase {
25	  case_id: string;
26	  brief: ProjectBrief;
27	  draftText: string;
28	  drifts: Array<{ passage: string; issue: string }>;
29	}
30	
31	interface Observation {
32	  field?: string;
33	  current?: string;
34	  suggested?: string;
35	  reason?: string;
36	}
37	
38	function observationsOf(raw: unknown): Observation[] {
39	  const list = (raw as { observations?: unknown })?.observations;
40	  return Array.isArray(list) ? (list as Observation[]) : [];
41	}
42	
43	/**
44	 * The brief fields a drift names. Issues lead with their fields
45	 * ("Tone and audience: ..."); without that label the whole sentence is read.
46	 */
47	function driftFields(issue: string): string[] {
48	  const label = issue.includes(":") ? issue.slice(0, issue.indexOf(":")) : issue;
49	  const lower = label.toLowerCase().replace(/success ?signal/g, "successsignal").replace(/working ?title/g, "workingtitle");
50	  return FIELDS.filter((field) => lower.includes(field.toLowerCase()));
51	}
52	
53	export const dossierSuite: Suite<DossierCase> = {
54	  name: "dossier",
55	  surface: "CLI twyne dossier check",
56	  load: () => readJsonl<DossierCase>("app/cases/dossier.jsonl"),
57	
58	  async run({ connection }, testCase) {
59	    const raw = await runCliJson(
60	      connection,
61	      ["dossier", "check", "--brief", "{brief.json}", "--file", "{draft.txt}"],
62	      {
63	        "brief.json": JSON.stringify(testCase.brief),
64	        "draft.txt": testCase.draftText,
65	      },
66	    );
67	    return {
68	      raw,
69	      output: observationsOf(raw)
70	        .map((o) => `${o.field}: ${o.current ?? ""} -> ${o.suggested ?? ""} (${o.reason ?? ""})`)
71	        .join("\n") || "(no observations)",
72	    };
73	  },
74	
75	  async score(_ctx, testCase, raw) {
76	    const observations = observationsOf(raw);
77	    const flagged = new Set(observations.map((o) => o.field));
78	    const drifts = testCase.drifts.map((drift) => driftFields(drift.issue));
79	    const found = drifts.filter((fields) => fields.some((field) => flagged.has(field)));
80	    const malformed = observations.filter(
81	      (o) =>
82	        !FIELDS.includes(o.field as (typeof FIELDS)[number]) ||
83	        typeof o.suggested !== "string" ||
84	        typeof o.reason !== "string",
85	    );
86	    const scores: Record<string, Score> = {
87	      contract: pass(
88	        Array.isArray((raw as { observations?: unknown })?.observations) &&
89	          malformed.length === 0,
90	        malformed.length ? `${malformed.length} malformed observation(s)` : undefined,
91	      ),
92	      drift_recall: {
93	        score: ratio(found.length, drifts.length),
94	        explanation: `flagged ${[...flagged].join(", ") || "nothing"}; ${found.length}/${drifts.length} drifts named (${drifts.map((fields) => fields.join("+")).join(", ")})`,
95	      },
96	      hosted: pass(
97	        (raw as { provider?: string })?.provider !== "local",
98	        (raw as { provider?: string })?.provider,
99	      ),
100	    };
101	    return scores;
102	  },
103	
104	  example: (testCase) => ({
105	    case_id: testCase.case_id,
106	    draftText: testCase.draftText,
107	    brief: JSON.stringify(testCase.brief),
108	    drifts: JSON.stringify(testCase.drifts),
109	  }),
110	};
111

1	/**
2	 * The dossier interview through `twyne_interview_turn`, on the conversations
3	 * in `evals/interview.jsonl` (shared with `bun run eval:interview`, which
4	 * replays the prompt directly; this suite runs the app's own turn handler and
5	 * protocol parser).
6	 *
7	 * A turn either asks one question, asks while recording what it has learned
8	 * (DOSSIER), or ends the interview (SYNTHESIZE). The checks compare that with
9	 * the expected behaviour and look for the fields the writer already gave.
10	 */
11	import { pass, ratio, type Score } from "../scoring";
12	import { readJsonl } from "./load";
13	import type { ProjectBrief, Suite } from "./types";
14	
15	export interface InterviewCase {
16	  case_id: string;
17	  mode: "first-run" | "refine";
18	  currentBrief: Partial<ProjectBrief> | null;
19	  messages: Array<{ author: "writer" | "interviewer"; text: string }>;
20	  expectedBehavior: "question" | "question_with_dossier" | "synthesize";
21	  expectedDossierFields: string[];
22	  tags?: string[];
23	}
24	
25	interface InterviewTurn {
26	  kind?: "question" | "synthesis";
27	  text?: string;
28	  draft?: { brief?: Record<string, string> };
29	  brief?: Record<string, string>;
30	  provider?: string;
31	}
32	
33	/**
34	 * The shared interview corpus records only a brief's answers; the app takes
35	 * the dossier as the browser files it.
36	 */
37	function filedBrief(brief: Partial<ProjectBrief>): ProjectBrief {
38	  return {
39	    attachments: [],
40	    completedAt: 1_790_000_000_000,
41	    updatedAt: 1_790_000_000_000,
42	    ...brief,
43	    answers: brief.answers ?? {},
44	  };
45	}
46	
47	function behaviourOf(turn: InterviewTurn): InterviewCase["expectedBehavior"] | "unknown" {
48	  if (turn.kind === "synthesis") return "synthesize";
49	  if (turn.kind === "question")
50	    return turn.draft?.brief && Object.keys(turn.draft.brief).length
51	      ? "question_with_dossier"
52	      : "question";
53	  return "unknown";
54	}
55	
56	export const interviewSuite: Suite<InterviewCase> = {
57	  name: "interview",
58	  surface: "MCP twyne_interview_turn",
59	  load: () => readJsonl<InterviewCase>("interview.jsonl"),
60	
61	  async run({ mcp }, testCase) {
62	    const raw = await mcp.call("twyne_interview_turn", {
63	      messages: testCase.messages,
64	      mode: testCase.mode,
65	      ...(testCase.currentBrief ? { currentBrief: filedBrief(testCase.currentBrief) } : {}),
66	    });
67	    const turn = raw as InterviewTurn;
68	    const recorded = turn.kind === "synthesis" ? turn.brief : turn.draft?.brief;
69	    return {
70	      raw,
71	      output:
72	        `${turn.kind ?? "?"}: ${turn.text ?? ""}` +
73	        (recorded ? `\n${JSON.stringify(recorded)}` : ""),
74	    };
75	  },
76	
77	  async score(_ctx, testCase, raw) {
78	    const turn = raw as InterviewTurn;
79	    const behaviour = behaviourOf(turn);
80	    const recorded = (turn.kind === "synthesis" ? turn.brief : turn.draft?.brief) ?? {};
81	    const captured = testCase.expectedDossierFields.filter(
82	      (field) => typeof recorded[field] === "string" && recorded[field].trim(),
83	    );
84	    // A question that also records a dossier still asks the right question.
85	    // The interview prompt (prompts/interview-system.md) also asks what kind of
86	    // advisors the writer wants before it synthesizes, so a complete brief with
87	    // no advisors yet earns one more question about them.
88	    const advisorsDiscussed = testCase.messages.some((m) =>
89	      /\badvis[eo]r|\beditors?\b/i.test(m.text),
90	    );
91	    const askedAdvisors =
92	      testCase.expectedBehavior === "synthesize" &&
93	      behaviour === "question_with_dossier" &&
94	      !advisorsDiscussed &&
95	      /\badvis[eo]r|\beditors?\b/i.test(turn.text ?? "");
96	    const protocolOk =
97	      askedAdvisors ||
98	      behaviour === testCase.expectedBehavior ||
99	      (testCase.expectedBehavior === "question" && behaviour === "question_with_dossier");
100	    const scores: Record<string, Score> = {
101	      protocol: {
102	        score: protocolOk ? 1 : 0,
103	        label: askedAdvisors ? "asked-advisors" : behaviour,
104	        explanation: askedAdvisors
105	          ? "brief complete except advisors; asked about them before synthesizing"
106	          : `expected ${testCase.expectedBehavior}, got ${behaviour}`,
107	      },
108	      dossier_fields: {
109	        // Nothing to capture yet is satisfied by capturing nothing.
110	        score: ratio(captured.length, testCase.expectedDossierFields.length) ?? 1,
111	        explanation: `captured ${captured.join(", ") || "none"} of ${testCase.expectedDossierFields.join(", ")}`,
112	      },
113	      hosted: pass(!!turn.provider && turn.provider !== "local", turn.provider),
114	    };
115	    // One question at a time: a question turn asks one (two marks allows a
116	    // clarifying aside), and a synthesis asks none.
117	    const questions = (turn.text?.match(/\?/g) ?? []).length;
118	    scores.one_question = pass(
119	      turn.kind === "question" ? questions >= 1 && questions <= 2 : questions === 0,
120	      `${questions} question mark(s) in a ${turn.kind ?? "?"} turn`,
121	    );
122	    return scores;
123	  },
124	
125	  example: (testCase) => ({
126	    case_id: testCase.case_id,
127	    mode: testCase.mode,
128	    messages: JSON.stringify(testCase.messages),
129	    currentBrief: JSON.stringify(testCase.currentBrief),
130	    expectedBehavior: testCase.expectedBehavior,
131	    expectedDossierFields: JSON.stringify(testCase.expectedDossierFields),
132	  }),
133	};
