1	/**
2	 * Arize hand-off for the app evals: datasets, experiments and traces.
3	 *
4	 * Datasets and experiments go through the `ax` CLI, which owns Arize
5	 * authentication (`ax profiles`). Each suite's corpus becomes a dataset named
6	 * for its content hash, so an experiment is always tied to the exact cases it
7	 * ran; editing a corpus starts a new dataset rather than silently changing an
8	 * old one. Runs are uploaded with flat `eval.<name>.score|label|explanation`
9	 * columns, which Arize reads as evaluation results.
10	 *
11	 * Traces go through the app's own OpenInference exporter
12	 * (`convex/arizeTracing.ts`): the local app is started with the Arize keys in
13	 * its environment, and each case runs inside a CHAIN span, so every model call
14	 * the app makes for that case lands in one trace.
15	 */
16	import { spawn } from "node:child_process";
17	import { createHash } from "node:crypto";
18	import { mkdtemp, rm, writeFile } from "node:fs/promises";
19	import { tmpdir } from "node:os";
20	import { join } from "node:path";
21	import { SpanStatusCode, trace } from "@opentelemetry/api";
22	import type { Score } from "./scoring";
23	
24	export interface AxOptions {
25	  space: string;
26	}
27	
28	async function ax(args: string[], stdin?: string): Promise<string> {
29	  const child = spawn("ax", [...args], { stdio: ["pipe", "pipe", "pipe"] });
30	  let stdout = "";
31	  let stderr = "";
32	  child.stdout.on("data", (chunk) => (stdout += chunk));
33	  child.stderr.on("data", (chunk) => (stderr += chunk));
34	  child.stdin.end(stdin ?? "");
35	  const code = await new Promise<number>((done) =>
36	    child.on("close", (exit) => done(exit ?? 1)),
37	  );
38	  if (code !== 0) {
39	    const detail = (stderr || stdout).replace(/\s+/g, " ").trim().slice(0, 400);
40	    throw new Error(`ax ${args.slice(0, 2).join(" ")} failed: ${detail}`);
41	  }
42	  return stdout;
43	}
44	
45	/** `ax -o json` prints the payload after any status lines. */
46	function jsonFrom(output: string): unknown {
47	  const start = output.search(/[[{]/);
48	  if (start < 0) throw new Error("ax returned no JSON");
49	  return JSON.parse(output.slice(start));
50	}
51	
52	export function corpusHash(rows: unknown[]): string {
53	  return createHash("sha256").update(JSON.stringify(rows)).digest("hex").slice(0, 8);
54	}
55	
56	/**
57	 * Find or create the dataset for a corpus. Returns the dataset ID and a map
58	 * from case_id to Arize example ID.
59	 */
60	export async function ensureDataset(
61	  options: AxOptions,
62	  name: string,
63	  rows: Array<Record<string, string | number | boolean> & { case_id: string }>,
64	): Promise<{ id: string; name: string; examples: Map<string, string> }> {
65	  let id: string | null = null;
66	  try {
67	    const found = jsonFrom(
68	      await ax(["datasets", "get", name, "--space", options.space, "-o", "json"]),
69	    ) as { id?: string };
70	    id = found.id ?? null;
71	  } catch {
72	    id = null;
73	  }
74	  if (!id) {
75	    const created = jsonFrom(
76	      await ax(
77	        ["datasets", "create", "--name", name, "--space", options.space, "--file", "-", "-o", "json"],
78	        JSON.stringify(rows),
79	      ),
80	    ) as { id?: string };
81	    if (!created.id) throw new Error(`ax did not return an ID for dataset ${name}`);
82	    id = created.id;
83	  }
84	  const exported = jsonFrom(
85	    await ax(["datasets", "export", id, "--stdout"]),
86	  ) as Array<{ id: string; additional_properties?: { case_id?: string } }>;
87	  const examples = new Map<string, string>();
88	  for (const example of exported) {
89	    const caseId = example.additional_properties?.case_id;
90	    if (caseId) examples.set(caseId, example.id);
91	  }
92	  return { id, name, examples };
93	}
94	
95	export interface ExperimentRun {
96	  example_id: string;
97	  output: string;
98	  /** False when the case errored before it could be scored. */
99	  ok: boolean;
100	  error?: string;
101	  scores: Record<string, Score>;
102	  metadata: Record<string, string | number | null>;
103	}
104	
105	/**
106	 * Arize wants a number in every row of an `eval.<name>.score` column, so the
107	 * runs are made rectangular before upload:
108	 *
109	 *  - a case that errored scores 0 on every metric, labelled "error": the
110	 *    writer got nothing, which is what the eval should show;
111	 *  - a metric that does not apply to some cases (weakness recall on a strong
112	 *    draft) is uploaded as labels, with "n/a" where it does not apply, rather
113	 *    than inventing a number. The local report keeps the scores either way.
114	 */
115	export function experimentRows(runs: ExperimentRun[]): {
116	  rows: Array<Record<string, unknown>>;
117	  labelOnly: string[];
118	} {
119	  const names = [...new Set(runs.flatMap((run) => Object.keys(run.scores)))];
120	  const labelOnly = names.filter((name) =>
121	    runs.some((run) => run.ok && typeof run.scores[name]?.score !== "number"),
122	  );
123	  const failed = runs.some((run) => !run.ok);
124	  // `ax` reads the file with pandas, which turns "1.00" into a number; a label
125	  // column must stay text, so labels are words or prefixed, never bare digits.
126	  const withLabel = names.filter(
127	    (name) =>
128	      failed ||
129	      labelOnly.includes(name) ||
130	      runs.some((run) => run.ok && run.scores[name]?.label),
131	  );
132	  const metadataKeys = [
133	    ...new Set(runs.flatMap((run) => Object.keys(run.metadata))),
134	  ];
135	  const rows = runs.map((run) => {
136	    const row: Record<string, unknown> = {
137	      example_id: run.example_id,
138	      output: run.output,
139	    };
140	    for (const name of names) {
141	      const score = run.scores[name];
142	      if (!run.ok) {
143	        if (!labelOnly.includes(name)) row[`eval.${name}.score`] = 0;
144	        row[`eval.${name}.label`] = "error";
145	        row[`eval.${name}.explanation`] = run.error ?? "the case did not run";
146	        continue;
147	      }
148	      if (!labelOnly.includes(name)) row[`eval.${name}.score`] = score?.score;
149	      if (withLabel.includes(name))
150	        row[`eval.${name}.label`] =
151	          score?.label ??
152	          (!labelOnly.includes(name)
153	            ? ""
154	            : typeof score?.score === "number"
155	              ? `score ${score.score.toFixed(2)}`
156	              : "n/a");
157	      row[`eval.${name}.explanation`] = score?.explanation ?? "";
158	    }
159	    for (const key of metadataKeys) row[key] = run.metadata[key] ?? "";
160	    return row;
161	  });
162	  return { rows, labelOnly };
163	}
164	
165	export async function uploadExperiment(
166	  datasetId: string,
167	  name: string,
168	  runs: ExperimentRun[],
169	): Promise<{ id: string | null; labelOnly: string[] }> {
170	  const { rows, labelOnly } = experimentRows(runs);
171	  const dir = await mkdtemp(join(tmpdir(), "twyne-arize-"));
172	  try {
173	    const file = join(dir, "runs.json");
174	    await writeFile(file, JSON.stringify(rows));
175	    const created = jsonFrom(
176	      await ax([
177	        "experiments",
178	        "create",
179	        "--name",
180	        name,
181	        "--dataset",
182	        datasetId,
183	        "--file",
184	        file,
185	        "-o",
186	        "json",
187	      ]),
188	    ) as { id?: string };
189	    return { id: created.id ?? null, labelOnly };
190	  } finally {
191	    await rm(dir, { recursive: true, force: true });
192	  }
193	}
194	
195	/**
196	 * Run `task` inside an OpenInference CHAIN span named for the case. The span
197	 * is a no-op unless the app's Arize tracer has been registered.
198	 */
199	export async function withCaseSpan<T>(
200	  attributes: { suite: string; caseId: string; experiment: string; input: string },
201	  task: () => Promise<{ value: T; output: string }>,
202	): Promise<{ value: T; traceId: string | null }> {
203	  const tracer = trace.getTracer("twyne-app-evals");
204	  return tracer.startActiveSpan(
205	    `eval.${attributes.suite}`,
206	    {
207	      attributes: {
208	        "openinference.span.kind": "CHAIN",
209	        // The OpenInference processor re-roots AI SDK spans whose parent does
210	        // not look like AI; an `ai.*` key keeps the case's model calls nested.
211	        "ai.telemetry.functionId": `eval.${attributes.suite}`,
212	        "input.value": attributes.input,
213	        "twyne.eval.suite": attributes.suite,
214	        "twyne.eval.case_id": attributes.caseId,
215	        "twyne.eval.experiment": attributes.experiment,
216	      },
217	    },
218	    async (span) => {
219	      const context = span.spanContext();
220	      const traceId = context.traceFlags ? context.traceId : null;
221	      try {
222	        const { value, output } = await task();
223	        span.setAttribute("output.value", output);
224	        span.setStatus({ code: SpanStatusCode.OK });
225	        return { value, traceId };
226	      } catch (error) {
227	        span.recordException(error as Error);
228	        span.setStatus({
229	          code: SpanStatusCode.ERROR,
230	          message: error instanceof Error ? error.message : String(error),
231	        });
232	        throw error;
233	      } finally {
234	        span.end();
235	      }
236	    },
237	  );
238	}
