1	/**
2	 * A scripted, OpenAI-compatible chat endpoint for the in-process app.
3	 *
4	 * The point is not to imitate a good editor. It is to answer each kind of
5	 * request the app sends in the shape the app expects, so a smoke run exercises
6	 * the real plumbing: prompt assembly, the `quote_passage` tool loop, JSON
7	 * parsing, rubric combination, interview protocol tags. A persona request is
8	 * answered with a tool call first and a note second; a judge gets a
9	 * `{score, rationale}` object; a rewrite gets `{replacement, rationale}`.
10	 *
11	 * Every response is deterministic for a given request, so tests can assert on
12	 * it, and every request is recorded by kind.
13	 */
14	import { createServer, type IncomingMessage, type Server } from "node:http";
15	
16	export type MockRequestKind =
17	  | "persona-tool-call"
18	  | "persona-note"
19	  | "judge"
20	  | "rewrite"
21	  | "dossier-check"
22	  | "interview"
23	  | "prose"
24	  | "research-extract"
25	  | "research-search"
26	  | "system-one";
27	
28	export interface MockModelServer {
29	  /** Base URL without `/v1`, as the app's RIVET_ENDPOINT expects. */
30	  url: string;
31	  calls: Array<{ kind: MockRequestKind; model: string }>;
32	  close(): Promise<void>;
33	}
34	
35	interface ChatMessage {
36	  role: string;
37	  content?: unknown;
38	  tool_calls?: unknown[];
39	}
40	
41	interface ChatBody {
42	  model?: string;
43	  stream?: boolean;
44	  messages?: ChatMessage[];
45	  tools?: Array<{ function?: { name?: string } }>;
46	}
47	
48	type Reply =
49	  | { kind: MockRequestKind; text: string }
50	  | {
51	      kind: "persona-tool-call";
52	      toolCall: { name: string; args: Record<string, unknown> };
53	    };
54	
55	const FILLER =
56	  /\b(in today's world|it is important|many experts|studies show|research suggests|at the end of the day|in order to|needless to say|a wide range of|plays a vital role)\b/gi;
57	
58	function hash(text: string): number {
59	  let h = 2166136261;
60	  for (let i = 0; i < text.length; i++) {
61	    h ^= text.charCodeAt(i);
62	    h = Math.imul(h, 16777619);
63	  }
64	  return h >>> 0;
65	}
66	
67	function textOf(content: unknown): string {
68	  if (typeof content === "string") return content;
69	  if (Array.isArray(content))
70	    return content
71	      .map((part) =>
72	        part && typeof part === "object" && "text" in part
73	          ? String((part as { text: unknown }).text)
74	          : "",
75	      )
76	      .join("");
77	  return "";
78	}
79	
80	/** The manuscript as the persona prompt frames it: `DRAFT (...)\n"""\n…\n"""`. */
81	function draftFrom(prompt: string): string {
82	  const fenced = prompt.match(/DRAFT \([^)]*\)\s*\n"""\n([\s\S]*?)\n"""/);
83	  if (fenced) return fenced[1];
84	  const tagged = prompt.match(/<draft>([\s\S]*?)<\/draft>/i);
85	  return tagged ? tagged[1] : prompt;
86	}
87	
88	function sentences(text: string): string[] {
89	  return (text.match(/[^.!?\n]+[.!?]/g) ?? [])
90	    .map((s) => s.trim())
91	    .filter((s) => s.split(/\s+/).length >= 6 && !s.includes("[…"));
92	}
93	
94	function personaName(system: string): string {
95	  return system.match(/You are ([^,.\n]+?),/)?.[1]?.trim() ?? "the editor";
96	}
97	
98	/** Higher for specific prose, lower for filler; a plausible, stable 2-9. */
99	function judgeScore(draft: string): number {
100	  const words = draft.split(/\s+/).filter(Boolean);
101	  const unique = new Set(words.map((w) => w.toLowerCase())).size;
102	  const diversity = words.length ? unique / words.length : 0;
103	  const filler = (draft.match(FILLER) ?? []).length;
104	  const raw = 3 + Math.round(diversity * 8) - Math.min(4, filler);
105	  return Math.max(2, Math.min(9, raw));
106	}
107	
108	function interviewReply(messages: ChatMessage[]): string {
109	  const writerTurns = messages.filter((m) => m.role === "user").length;
110	  const brief = {
111	    workingTitle: "Salt Roads",
112	    format: "travel essay",
113	    audience: "readers of a literary travel quarterly",
114	    goal: "make the old salt road feel walked, not described",
115	    tone: "plain, observant, wry",
116	    constraints: "under 3,000 words",
117	    successSignal: "an editor asks to see the next draft",
118	  };
119	  if (writerTurns >= 4) {
120	    return `That gives me enough to work from.\n\nSYNTHESIZE: ${JSON.stringify({
121	      brief,
122	      confidence: { workingTitle: "high", audience: "medium", goal: "medium" },
123	    })}`;
124	  }
125	  return `Who do you most want to finish this piece?\n\nDOSSIER: ${JSON.stringify({
126	    brief: { workingTitle: brief.workingTitle },
127	    confidence: { workingTitle: "medium" },
128	  })}`;
129	}
130	
131	/** A small, always-different edit: hedges out, then a clause, then a contraction. */
132	function tighten(original: string): string {
133	  const steps: Array<(text: string) => string> = [
134	    (text) =>
135	      text
136	        .replace(/\b(really|very|quite|actually|just|simply|basically|clearly|obviously|certainly|perhaps|somewhat|rather)\s+/gi, "")
137	        .replace(/\bin order to\b/gi, "to")
138	        .replace(/\bdue to the fact that\b/gi, "because")
139	        .replace(/\bit is important to note that\s*/gi, ""),
140	    (text) => text.replace(/,[^,]{3,80},/, ","),
141	    (text) =>
142	      text
143	        .replace(/\bis not\b/, "isn't")
144	        .replace(/\bdoes not\b/, "doesn't")
145	        .replace(/\bit is\b/i, (m) => (m[0] === "I" ? "It's" : "it's")),
146	  ];
147	  let text = original;
148	  for (const step of steps) {
149	    const next = step(text).replace(/\s{2,}/g, " ").trim();
150	    if (next && next !== original.trim()) return next;
151	    text = next || text;
152	  }
153	  return text;
154	}
155	
156	export function scriptedReply(body: ChatBody): Reply {
157	  const messages = body.messages ?? [];
158	  const system = messages
159	    .filter((m) => m.role === "system")
160	    .map((m) => textOf(m.content))
161	    .join("\n");
162	  const user = messages
163	    .filter((m) => m.role === "user")
164	    .map((m) => textOf(m.content))
165	    .join("\n");
166	  const all = `${system}\n${user}`;
167	  const hasQuoteTool = (body.tools ?? []).some(
168	    (t) => t.function?.name === "quote_passage",
169	  );
170	  const toolResults = messages.filter((m) => m.role === "tool");
171	
172	  if (/\bDOSSIER:|\bSYNTHESIZE:/.test(system)) {
173	    return { kind: "interview", text: interviewReply(messages) };
174	  }
175	  if (/proactive research librarian/.test(system)) {
176	    // Flag the sentences that carry a figure, a year or a quotation; the
177	    // shape is what the app's parseResearchTargets reads.
178	    const draft = user.match(/Draft:\n"""\n([\s\S]*?)\n"""/)?.[1] ?? user;
179	    const flagged = sentences(draft)
180	      .filter((s) => /\d|["“]/.test(s))
181	      .slice(0, 6);
182	    return {
183	      kind: "research-extract",
184	      text: JSON.stringify({
185	        targets: flagged.map((anchor, i) => ({
186	          kind: /["“]/.test(anchor) ? "quote" : /\b1[5-9]\d\d|20\d\d\b/.test(anchor) ? "event" : "statistic",
187	          anchor: anchor.slice(0, 180),
188	          reason: "States something a reader may check.",
189	          query: anchor.replace(/["“”]/g, "").split(/\s+/).slice(0, 9).join(" "),
190	          importance: Math.max(1, 5 - i),
191	        })),
192	      }),
193	    };
194	  }
195	  if (/"replacement"/.test(all)) {
196	    const original = user.match(/PASSAGE:\n"([\s\S]*)"\s*$/)?.[1] ?? "";
197	    const replacement = tighten(original);
198	    return {
199	      kind: "rewrite",
200	      text: JSON.stringify({
201	        replacement,
202	        rationale: "Cut the hedges so the claim stands on its own.",
203	      }),
204	    };
205	  }
206	  if (/\bobservations\b/.test(system) && /dossier/i.test(system)) {
207	    return { kind: "dossier-check", text: JSON.stringify({ observations: [] }) };
208	  }
209	  if (/"score"\s*:/.test(all)) {
210	    const draft = draftFrom(user);
211	    const first = sentences(draft)[0] ?? "the opening";
212	    return {
213	      kind: "judge",
214	      text: JSON.stringify({
215	        score: judgeScore(draft),
216	        rationale: `The draft is judged on "${first.slice(0, 80)}".`,
217	      }),
218	    };
219	  }
220	  if (hasQuoteTool) {
221	    const draft = draftFrom(user);
222	    const pool = sentences(draft);
223	    if (toolResults.length === 0 && pool.length > 0) {
224	      return {
225	        kind: "persona-tool-call",
226	        toolCall: {
227	          name: "quote_passage",
228	          args: { query: pool[hash(system) % pool.length] },
229	        },
230	      };
231	    }
232	    const quoted =
233	      toolResults
234	        .map((m) => textOf(m.content))
235	        .join("\n")
236	        .match(/"passage"\s*:\s*"((?:[^"\\]|\\.)*)"/)?.[1] ?? pool[0] ?? "";
237	    return {
238	      kind: "persona-note",
239	      text:
240	        `"${quoted.replace(/\\"/g, '"')}" carries more weight than the paragraph around it gives it. ` +
241	        `As ${personaName(system)}, I would make the next sentence earn it with one concrete detail. ` +
242	        `Next move: name the detail.`,
243	    };
244	  }
245	  return {
246	    kind: "prose",
247	    text: "The draft has a clear spine. Revise the middle so each paragraph advances the claim, then cut the closing summary.",
248	  };
249	}
