251	function completion(model: string, reply: Reply) {
252	  const message =
253	    "toolCall" in reply
254	      ? {
255	          role: "assistant",
256	          content: null,
257	          tool_calls: [
258	            {
259	              id: `call_${hash(JSON.stringify(reply.toolCall.args)).toString(16)}`,
260	              type: "function",
261	              function: {
262	                name: reply.toolCall.name,
263	                arguments: JSON.stringify(reply.toolCall.args),
264	              },
265	            },
266	          ],
267	        }
268	      : { role: "assistant", content: reply.text };
269	  return {
270	    id: "chatcmpl-mock",
271	    object: "chat.completion",
272	    created: 1_790_000_000,
273	    model,
274	    choices: [
275	      {
276	        index: 0,
277	        message,
278	        finish_reason: "toolCall" in reply ? "tool_calls" : "stop",
279	      },
280	    ],
281	    usage: { prompt_tokens: 100, completion_tokens: 40, total_tokens: 140 },
282	  };
283	}
284	
285	function streamChunks(model: string, reply: Reply): string {
286	  const base = { id: "chatcmpl-mock", object: "chat.completion.chunk", created: 1_790_000_000, model };
287	  const delta =
288	    "toolCall" in reply
289	      ? {
290	          role: "assistant",
291	          tool_calls: [
292	            {
293	              index: 0,
294	              id: "call_mock",
295	              type: "function",
296	              function: {
297	                name: reply.toolCall.name,
298	                arguments: JSON.stringify(reply.toolCall.args),
299	              },
300	            },
301	          ],
302	        }
303	      : { role: "assistant", content: reply.text };
304	  const events = [
305	    { ...base, choices: [{ index: 0, delta, finish_reason: null }] },
306	    {
307	      ...base,
308	      choices: [
309	        {
310	          index: 0,
311	          delta: {},
312	          finish_reason: "toolCall" in reply ? "tool_calls" : "stop",
313	        },
314	      ],
315	      usage: { prompt_tokens: 100, completion_tokens: 40, total_tokens: 140 },
316	    },
317	  ];
318	  return events.map((e) => `data: ${JSON.stringify(e)}\n\n`).join("") + "data: [DONE]\n\n";
319	}
