327	interface JudgementRequest {
328	  model?: string;
329	  state?: Record<string, string>;
330	  questions?: Record<string, { type?: string; criteria?: unknown }>;
331	}
332	
333	/**
334	 * The research claim check: does `claimN` need a source? Sentences with a
335	 * figure, a year or an attributed quotation do (0.9); the rest do not (0.2),
336	 * so the hosted strategy's 0.6 cutoff is exercised in both directions.
337	 */
338	function claimCheckAnswer(claim: string | undefined): number {
339	  if (!claim) return 0.05;
340	  return /\d|["\u201c][^"\u201d]{8,}["\u201d]|\baccording to\b/i.test(claim) ? 0.9 : 0.2;
341	}
342	
343	/**
344	 * System One (TypeSafe) answers. The editorial review gate judges every note
345	 * fit to release, so its plumbing runs without a redraft; research claim
346	 * checks follow `claimCheckAnswer`.
347	 */
348	function judgementAnswers(request: JudgementRequest) {
349	  return Object.fromEntries(
350	    Object.entries(request.questions ?? {}).map(([id, question]) => {
351	      if (question.type === "noul")
352	        return [
353	          id,
354	          {
355	            type: "noul",
356	            noul: /^claim\d+$/.test(id)
357	              ? claimCheckAnswer(request.state?.[id])
358	              : 0.05,
359	          },
360	        ];
361	      if (question.type === "choice") {
362	        const options = Object.keys((question.criteria ?? {}) as Record<string, unknown>);
363	        const choice = options[0] ?? "";
364	        return [id, { type: "choice", choice, probabilities: { [choice]: 1 }, confidence: 0.9 }];
365	      }
366	      const levels = Array.isArray(question.criteria) ? question.criteria : ["", ""];
367	      const top = levels.length - 1;
368	      return [
369	        id,
370	        {
371	          type: "score",
372	          score: top,
373	          legend: Object.fromEntries(levels.map((text, i) => [String(i), String(text)])),
374	          probabilities: { [String(top)]: 1 },
375	          confidence: 0.9,
376	        },
377	      ];
378	    }),
379	  );
380	}
