382	export async function startMockModel(): Promise<MockModelServer> {
383	  const calls: MockModelServer["calls"] = [];
384	  const server: Server = createServer(async (req, res) => {
385	    if (req.method === "POST" && req.url?.endsWith("/v1/systemone")) {
386	      const request = JSON.parse(await readBody(req)) as JudgementRequest;
387	      calls.push({ kind: "system-one", model: request.model ?? "jev" });
388	      res.writeHead(200, { "content-type": "application/json" });
389	      res.end(
390	        JSON.stringify({
391	          model: "jev-mock",
392	          answers: judgementAnswers(request),
393	          usage: { input_tokens: 400, output_tokens: 0 },
394	        }),
395	      );
396	      return;
397	    }
398	    if (req.method === "POST" && req.url?.endsWith("/v1/search")) {
399	      // A research provider (RESEARCH_PROVIDER=custom): three stable hits
400	      // named for the query, the first two with the fields ranking rewards.
401	      const { query = "" } = JSON.parse(await readBody(req)) as { query?: string };
402	      calls.push({ kind: "research-search", model: "search" });
403	      const slug = query.toLowerCase().replace(/[^a-z0-9]+/g, "-").slice(0, 48);
404	      res.writeHead(200, { "content-type": "application/json" });
405	      res.end(
406	        JSON.stringify({
407	          results: [
408	            {
409	              title: `${query.slice(0, 60)} — encyclopedia entry`,
410	              url: `https://encyclopedia.example/${slug}`,
411	              snippet: `A reference article on ${query.slice(0, 80)}, with dates, figures and sources.`,
412	              author: "Reference Desk",
413	              publisher: "Encyclopedia Example",
414	            },
415	            {
416	              title: `Primary record: ${query.slice(0, 50)}`,
417	              url: `https://archive.example/${slug}`,
418	              snippet: `Archival material concerning ${query.slice(0, 80)}.`,
419	              publisher: "Archive Example",
420	            },
421	            { title: "Forum thread", url: `https://forum.example/${slug}`, snippet: "" },
422	          ],
423	        }),
424	      );
425	      return;
426	    }
427	    if (req.method !== "POST" || !req.url?.endsWith("/chat/completions")) {
428	      res.writeHead(404).end();
429	      return;
430	    }
431	    let body: ChatBody;
432	    try {
433	      body = JSON.parse(await readBody(req)) as ChatBody;
434	    } catch {
435	      res.writeHead(400).end();
436	      return;
437	    }
438	    const model = body.model ?? "mock";
439	    const reply = scriptedReply(body);
440	    calls.push({ kind: reply.kind, model });
441	    if (body.stream) {
442	      res.writeHead(200, { "content-type": "text/event-stream" });
443	      res.end(streamChunks(model, reply));
444	      return;
445	    }
446	    res.writeHead(200, { "content-type": "application/json" });
447	    res.end(JSON.stringify(completion(model, reply)));
448	  });
449	  await new Promise<void>((resolve) =>
450	    server.listen(0, "127.0.0.1", () => resolve()),
451	  );
452	  const { port } = server.address() as { port: number };
453	  return {
454	    url: `http://127.0.0.1:${port}`,
455	    calls,
456	    close: () =>
457	      new Promise<void>((resolve) => server.close(() => resolve())),
458	  };
459	}
