   124	export async function runCliJson(
   125	  connection: Connection,
   126	  args: string[],
   127	  files: Record<string, string> = {},
   128	): Promise<unknown> {
   129	  const dir = await mkdtemp(join(tmpdir(), "twyne-cli-"));
   130	  try {
   131	    const paths: Record<string, string> = {};
   132	    for (const [name, content] of Object.entries(files)) {
   133	      paths[name] = join(dir, name);
   134	      await writeFile(paths[name], content);
   135	    }
   136	    const argv = args.map((arg) =>
   137	      arg.replace(/\{([^}]+)\}/g, (match, name: string) => paths[name] ?? match),
   138	    );
   139	    const child = spawn(
   140	      process.execPath,
   141	      [join(TOOLS_DIR, "src/cli.ts"), ...argv, "--json"],
   142	      {
   143	        env: {
   144	          PATH: process.env.PATH ?? "",
   145	          HOME: process.env.HOME ?? "",
   146	          TWYNE_API_URL: connection.apiUrl,
   147	          TWYNE_ACCESS_TOKEN: connection.token,
   148	        },
   149	        stdio: ["ignore", "pipe", "pipe"],
   150	      },
   151	    );
   152	    let stdout = "";
   153	    let stderr = "";
   154	    child.stdout.on("data", (chunk) => (stdout += chunk));
   155	    child.stderr.on("data", (chunk) => (stderr += chunk));
   156	    const code = await new Promise<number>((done) =>
   157	      child.on("close", (exit) => done(exit ?? 1)),
   158	    );
   159	    if (code !== 0)
   160	      throw new Error(`twyne ${args[0]} exited ${code}: ${stderr.trim()}`);
   161	    return JSON.parse(stdout);
   162	  } finally {
   163	    await rm(dir, { recursive: true, force: true });
