317	    const via = ownKey ? "byok" : transport();
318	    // Not an error: Jev is a tier of a ladder, and every surface above it has
319	    // a working Tier 0/1 answer already. Degrade silently, never throw.
320	    if (via === "none") return { ok: false, error: "unconfigured" };
321	
322	    const ids = Object.keys(args.questions);
323	    if (ids.length === 0) return { ok: false, error: "no questions" };
324	    if (ids.length > MAX_QUESTIONS) {
325	      return { ok: false, error: `too many questions (${ids.length})` };
326	    }
327	
328	    const stateChars = Object.values(args.state).reduce(
329	      (n, s) => n + s.length,
330	      0,
331	    );
332	    if (stateChars > MAX_STATE_CHARS) {
333	      return { ok: false, error: "state too large" };
334	    }
335	
336	    if (!caller) return { ok: false, error: "signed out" };
337	    let questions;
338	    try {
339	      questions = judgementQuestions(args.questions);
340	    } catch {
341	      return { ok: false, error: "malformed" };
342	    }
343	    // The writer's own key spends the writer's own quota, not Twyne's.
344	    if (via !== "byok") {
345	      const isPro = await userIsPro(ctx, caller.subject);
346	      await consumeRateLimit(ctx, {
347	        action: "systemOne:ask",
348	        identifier: caller.tokenIdentifier,
349	        ...(isPro ? RATE_LIMITS.systemOne : RATE_LIMITS.systemOneFree),
350	      });
351	    }
352	
353	    // The gateway resolves `judgement` to a concrete Jev version, so the model
354	    // is only named explicitly on the direct developer path.
355	    const payload = {
356	      model: args.model ?? DEFAULT_MODEL,
357	      state: args.state,
358	      questions,
359	    };
