372	    if (!result.ok) return { ok: false, transport: via, error: result.error };
373	    if (!validJudgementResponse(result.body, args.questions))
374	      return { ok: false, transport: via, error: "provider" };
375	    return {
376	      ok: true,
377	      transport: via,
378	      model: result.body.model,
379	      answers: result.body.answers,
380	      usage: result.body.usage,
381	    };
382	  }
383	}
