     7	/** Local development means a loopback Convex runtime, never a hosted deployment. */
     8	export function directJudgementKey(
     9	  env: Record<string, string | undefined>,
    10	): string | null {
    11	  const key = env.TYPESAFE_API_KEY?.trim();
    12	  if (!key) return null;
    13	  try {
    14	    const url = new URL(env.CONVEX_CLOUD_URL || env.CONVEX_SITE_URL || "");
