    23	/** Keep the app's ordered labels, emit the current HTTP Choice map contract. */
    24	export function judgementQuestions(
    25	  questions: Record<string, JudgementQuestion>,
    26	) {
    27	  const entries = Object.entries(questions);
    28	  if (!entries.length || entries.length > 64) throw new Error("question limit");
    29	  const normalized = Object.fromEntries(
    30	    entries.map(([id, q]) => {
    31	      if (!q.instructions.trim()) throw new Error("missing instructions");
    32	      if (q.type === "noul")
    33	        return [id, { type: q.type, instructions: q.instructions }];
    34	      const options = q.criteria ?? [];
    35	      if (
    36	        options.length < 2 ||
    37	        options.length > 64 ||
    38	        options.some((value) => !value.trim()) ||
    39	        new Set(options).size !== options.length
    40	      ) {
    41	        throw new Error("invalid criteria");
    42	      }
    43	      return [
    44	        id,
    45	        {
    46	          type: q.type,
    47	          instructions: q.instructions,
    48	          criteria:
    49	            q.type === "choice"
    50	              ? Object.fromEntries(options.map((value) => [value, null]))
    51	              : options,
    52	        },
    53	      ];
    54	    }),
    55	  );
    56	  if (JSON.stringify(normalized).length > 96_000)
    57	    throw new Error("question limit");
    58	  return normalized;
    59	}
