    61	export function validJudgementResponse(
    62	  value: unknown,
    63	  questions: Record<string, JudgementQuestion>,
    64	): value is {
    65	  model: string;
    66	  answers: Record<string, unknown>;
    67	  usage: { input_tokens: number; output_tokens: number };
    68	} {
    69	  if (!value || typeof value !== "object") return false;
    70	  const p = value as Record<string, unknown>;
    71	  if (
    72	    typeof p.model !== "string" ||
    73	    !p.answers ||
    74	    typeof p.answers !== "object" ||
    75	    Array.isArray(p.answers)
    76	  )
    77	    return false;
    78	  const usage = p.usage as Record<string, unknown> | undefined;
    79	  if (
    80	    !usage ||
    81	    ![usage.input_tokens, usage.output_tokens].every(
    82	      (n) => typeof n === "number" && Number.isSafeInteger(n) && n >= 0,
    83	    )
    84	  )
    85	    return false;
    86	  return Object.entries(questions).every(([id, q]) => {
    87	    const a = (p.answers as Record<string, Record<string, unknown>>)[id];
    88	    if (!a || a.type !== q.type) return false;
    89	    if (q.type === "noul")
    90	      return typeof a.noul === "number" && a.noul >= 0 && a.noul <= 1;
    91	    if (
    92	      typeof a.confidence !== "number" ||
    93	      !Number.isFinite(a.confidence) ||
    94	      a.confidence < 0 ||
    95	      a.confidence > 1 ||
    96	      !a.probabilities ||
    97	      typeof a.probabilities !== "object" ||
    98	      Array.isArray(a.probabilities)
    99	    )
   100	      return false;
   101	    const probabilities = Object.values(a.probabilities);
   102	    if (
   103	      !probabilities.length ||
   104	      !probabilities.every(
   105	        (n) => typeof n === "number" && Number.isFinite(n) && n >= 0 && n <= 1,
   106	      )
   107	    )
   108	      return false;
   109	    if (q.type === "choice")
   110	      return (
   111	        typeof a.choice === "string" && Boolean(q.criteria?.includes(a.choice))
   112	      );
   113	    return (
   114	      typeof a.score === "number" &&
   115	      Number.isFinite(a.score) &&
   116	      a.score >= 0 &&
   117	      a.score <= (q.criteria?.length ?? 0) - 1 &&
   118	      a.legend !== null &&
   119	      typeof a.legend === "object" &&
   120	      !Array.isArray(a.legend) &&
   121	      JSON.stringify(Object.values(a.legend)) === JSON.stringify(q.criteria)
   122	    );
   123	  });
   124	}

