167	      EXTRACTION_PATH,
168	      token,
169	      {
170	        method: "POST",
171	        signal: AbortSignal.timeout(40_000),
172	        body: JSON.stringify(body),
173	        // Fresh per attempt, as in systemOne: an edited draft is a new read.
174	        headers: { "idempotency-key": crypto.randomUUID() },
175	      },
176	      { issuer: notOrganicIssuer(), feature: EXTRACTION_FEATURE },
177	    );
178	    return { ok: true, body: result };
179	  } catch (error) {
180	    const message = error instanceof Error ? error.message : "";
181	    const status =
182	      /^Not Organic (?:API|token exchange) failed \((\d{3})\)/.exec(
183	        message,
184	      )?.[1];
185	    return {
186	      ok: false,
187	      error: status ? statusError(Number(status)) : extractionError(error),
188	    };
189	  }
