361	/**
362	 * The extraction itself. `caller` is null only on the public path when nobody
363	 * is signed in; the size checks ahead of the sign-in gate keep their order.
364	 */
365	async function extractCore(
366	  ctx: ActionCtx,
367	  caller: HostedCaller | null,
368	  args: ObjectType<typeof extractArgs>,
369	): Promise<ExtractResult> {
370	  {
371	    const via = transport();
372	    if (via === "none") return { ok: false, error: "unconfigured" };
373	    const names = Object.keys(args.fields);
374	    if (names.length === 0) return { ok: false, error: "no fields" };
375	    if (names.length > MAX_FIELDS)
376	      return { ok: false, error: `too many fields (${names.length})` };
377	    if (!args.state?.trim()) return { ok: false, error: "empty state" };
378	    if (args.state.length > MAX_STATE_CHARS)
379	      return { ok: false, error: "state too large" };
380	
381	    try {
382	      if (!caller) return { ok: false, error: "signed out" };
383	      const isPro = await userIsPro(ctx, caller.subject);
384	      await consumeRateLimit(ctx, {
385	        action: "extraction:extract",
386	        identifier: caller.tokenIdentifier,
387	        ...(isPro ? RATE_LIMITS.extraction : RATE_LIMITS.extractionFree),
388	      });
389	
390	      const body = {
391	        state: args.state,
392	        fields: args.fields,
393	        ...(args.reference_date ? { reference_date: args.reference_date } : {}),
394	        ...(args.options ? { options: args.options } : {}),
395	      };
396	      const result =
397	        via === "notorganic"
398	          ? await extractNotOrganic(ctx, caller, body)
399	          : await extractDirect(directCredentials()!, body);
400	      if (!result.ok) return { ok: false, transport: via, error: result.error };
401	      const response = validatedBody(result.body, args, via);
402	      if (!response) return { ok: false, transport: via, error: "provider" };
403	      const usage = response.usage;
404	      return {
405	        ok: true,
406	        transport: via,
407	        model: response.model,
408	        answers: response.answers,
409	        truncated: response.truncated,
410	        ...(usage &&
411	        typeof usage.input_tokens === "number" &&
412	        typeof usage.output_tokens === "number"
413	          ? {
414	              usage: {
415	                input_tokens: usage.input_tokens,
416	                output_tokens: usage.output_tokens,
417	                ...(typeof usage.passes === "number"
418	                  ? { passes: usage.passes }
419	                  : {}),
420	              },
421	            }
422	          : {}),
423	      };
