      filled(onFile[field]) && recorded[field]?.trim() === onFile[field]?.trim();
    const filedFields = BRIEF_FIELDS.filter((field) => filled(recorded[field]));
    const newlyFiled = filedFields.filter((field) => !carried(field));
    const question = turn.kind === "question" ? (turn.text ?? "") : null;

    const [clairic, blind, record] = await Promise.all([
      extract ? askClairic(extract, { state: conversation.text, fields: CLAIRIC_BRIEF_FIELDS }) : null,
      jev ? (async () => {
        const request = jevInterviewRequest({ conversation: conversation.text, question });
        return { request, answers: await askJev(jev, request.state, request.questions) };
      })() : null,
      jev && newlyFiled.length
        ? (async () => {
            const request = jevRecordRequest({
              conversation: conversation.text,
              recorded: Object.fromEntries(newlyFiled.map((f) => [f, recorded[f]])),
            });
            return { request, answers: await askJev(jev, request.state, request.questions) };
          })()
        : null,
    ]);

    if (extract && clairic) {
      if (!clairic.ok) {
        const failed: Score = { score: null, label: "clairic-error", explanation: clairic.error };
        scores.clairic_field_recall = failed;
        scores.clairic_field_support = failed;
      } else {
        const known = Object.fromEntries(
          BRIEF_FIELDS.map((field) => [
            field,
            filled(onFile[field]) || saidByWriter(clairic.answers[field], conversation.turns) ? 1 : 0,
          ]),
        ) as Record<BriefField, number>;
        const stated = BRIEF_FIELDS.filter((field) => known[field]);
        const missed = stated.filter((field) => !filled(recorded[field]));
        const unsupported = filedFields.filter((field) => !known[field]);
        const detail = BRIEF_FIELDS.filter((field) => clairic.answers[field]?.value != null)
          .map((field) => `${field} "${String(clairic.answers[field].value).slice(0, 40)}"`)
          .join("; ");
        scores.clairic_field_recall = {
          score: ratio(stated.length - missed.length, stated.length) ?? 1,
          label: stated.length ? undefined : "nothing stated",
          explanation:
            `the writer stated ${stated.join(", ") || "nothing"}` +
            (missed.length ? `; not filed: ${missed.join(", ")}` : "") +
            (detail ? ` (Clairic: ${detail})` : ""),
          items: known,
        };
        scores.clairic_field_support = {
          score: ratio(filedFields.length - unsupported.length, filedFields.length) ?? 1,
          label: filedFields.length ? undefined : "nothing filed",
          explanation: unsupported.length
            ? `filed without the writer stating it: ${unsupported.join(", ")}`
            : "every filed field was stated by the writer or already on file",
        };
      }
    }

    if (blind) {
      const { request, answers } = blind;
      const known = Object.fromEntries(
        BRIEF_FIELDS.map((field) => [
          field,
          filled(onFile[field]) ? 1 : answers[request.statedIds[field]]?.score,
        ]),
      ) as Record<BriefField, number | null | undefined>;
      const readable = BRIEF_FIELDS.filter((field) => typeof known[field] === "number");
      const expected = readable.reduce((sum, field) => sum + (known[field] as number), 0);
      const hit = readable.reduce((sum, field) => sum + (filled(recorded[field]) ? (known[field] as number) : 0), 0);
      scores.jev_field_recall = !readable.length
        ? { score: null, label: "jev-error", explanation: answers[request.statedIds.workingTitle]?.explanation }
        : {
            // Expected recall: each field weighted by Jev's probability that
            // the writer stated it.
            score: expected > 0 ? hit / expected : 1,
            label: expected > 0 ? undefined : "nothing stated",
            explanation: readable.map((field) => `${field} ${(known[field] as number).toFixed(2)}`).join(", "),
            items: Object.fromEntries(readable.map((field) => [field, known[field] as number])),
          };
      if (question !== null) {
        scores.jev_question_value = answers.jev_question_value;
        scores.jev_no_repeat = jevNot(answers.repeats, "new ground", "asks again");
      }
    }
    if (jev) {
      scores.jev_record_faithful = record
        ? jevShare(record.answers, record.request.ids)
        : { score: 1, label: filedFields.length ? "nothing new filed" : "nothing filed", items: {} };
    }
    return scores;
  },

  example: (testCase) => ({
    case_id: testCase.case_id,
    mode: testCase.mode,
    messages: JSON.stringify(testCase.messages),
    currentBrief: JSON.stringify(testCase.currentBrief),
    expectedBehavior: testCase.expectedBehavior,
    expectedDossierFields: JSON.stringify(testCase.expectedDossierFields),
  }),
};

