/** Mean, spread and 95% interval of one metric over the cases that have it. */
export function summarizeValues(
  points: Array<{ value: number | null | undefined; cluster: string }>,
): MetricSummary {
  const present = points.filter(
    (p): p is { value: number; cluster: string } =>
      typeof p.value === "number" && Number.isFinite(p.value),
  );
  const n = present.length;
  if (n === 0)
    return { mean: null, n: 0, ci: null, se: null, sd: null, clusters: 0, method: null };
  const values = present.map((p) => p.value);
  const mean = average(values);
  const sd = sampleSd(values);
  const { se, clusters } = clusterSe(
    values,
    present.map((p) => p.cluster),
  );
  if (clusters < 2 || se === null)
    return { mean, n, ci: null, se: null, sd, clusters, method: null };

  const binary = values.every((v) => v === 0 || v === 1);
  if (binary || se === 0) {
    // Effective sample size: shrink n by the design effect of clustering.
    // Identical values carry no information about it, so assume the worst:
    // one observation per cluster.
    const iid = sd !== null ? (sd * sd) / n : 0;
    let effective = n;
    if (clusters < n)
      effective =
        iid > 0 && se > 0
          ? Math.min(n, Math.max(clusters, (n * iid) / (se * se)))
          : clusters;
    return { mean, n, ci: wilson(clamp01(mean), effective), se, sd, clusters, method: "wilson" };
  }
  const half = tCritical(clusters - 1) * se;
  return {
    mean,
    n,
    ci: [clamp01(mean - half), clamp01(mean + half)],
    se,
    sd,
    clusters,
    method: "t",
  };
}

