// Probe: which phrasing of the observation-truth question separates true complaints from false alarms?
import { readFileSync } from "node:fs";
const key = process.env.TYPESAFE_API_KEY!;
const cases = Object.fromEntries(readFileSync(process.argv[2], "utf8").split("\n").filter(Boolean).map((l) => { const c = JSON.parse(l); return [c.case_id, c]; }));
const items: Array<{ case: string; obs: string; truth: 0 | 1 }> = [
  { case: "dossier-aligned-library-welcome", obs: "goal: Draft exceeds the stated purpose by adding material-care and revisit content.", truth: 0 },
  { case: "dossier-aligned-library-welcome", obs: "constraints: Specialist terms appear without definition, violating the no-prior-knowledge assumption.", truth: 0 },
  { case: "dossier-aligned-library-welcome", obs: "tone: The draft scolds first-time visitors and warns them they will be turned away if they ask basic questions.", truth: 0 },
  { case: "dossier-goal-compost-pilot", obs: "constraints: dossier mandates the link and Friday deadline appear in the first paragraph and again at the end", truth: 1 },
  { case: "dossier-goal-compost-pilot", obs: "goal: goal is to get at least 100 households to sign up before the Friday deadline; the draft never asks them to sign up", truth: 1 },
  { case: "dossier-goal-compost-pilot", obs: "tone: The email is written in a hostile, accusatory tone toward residents.", truth: 0 },
  { case: "dossier-goal-compost-pilot", obs: "audience: The draft is addressed to council staff rather than to residents of the pilot area.", truth: 0 },
  { case: "dossier-constraint-q3-update", obs: "constraints: names the competitor Meridian Freight, which the brief forbids", truth: 1 },
  { case: "dossier-constraint-q3-update", obs: "constraints: gives the gross margin and cash flow, beyond the revenue growth percentage the brief allows", truth: 1 },
  { case: "dossier-constraint-q3-update", obs: "tone: The note is written in stiff legal language rather than candid, warm and plain.", truth: 0 },
];
const variants: Record<string, (i: number) => any> = {
  noul_present: () => ({ type: "noul", instructions: "Is the problem that `observation` describes actually present in `draft`, judged against `brief`?" }),
  noul_quote: () => ({ type: "noul", instructions: "Can you point to a sentence in `draft` that shows the problem `observation` describes? Answer no if the draft already does what `observation` says it fails to do." }),
  choice_relation: () => ({ type: "choice", instructions: "How does `draft` relate to the complaint in `observation`?", criteria: {
    contradicts: "The draft already does what the complaint says it fails to do, or does not do what the complaint says it does",
    shows: "Specific passages of the draft show the problem the complaint describes",
    unclear: "The draft gives too little to tell either way" } }),
};
const results: Record<string, number[]> = Object.fromEntries(Object.keys(variants).map((v) => [v, []]));
for (const item of items) {
  const c = cases[item.case];
  const brief = Object.entries(c.brief.answers).map(([k, v]) => `${k}: ${v}`).join("\n");
  const questions = Object.fromEntries(Object.entries(variants).map(([name, make]) => [name, make(0)]));
  const res = await fetch("https://api.typesafe.ai/v1/systemone", { method: "POST", headers: { "content-type": "application/json", authorization: `Bearer ${key}` },
    body: JSON.stringify({ model: "jev-latest", state: { brief, draft: c.draftText, observation: item.obs }, questions }) });
  const json: any = await res.json();
  const row: string[] = [];
  for (const name of Object.keys(variants)) {
    const a = json.answers?.[name];
    const p = a?.type === "noul" ? a.noul : a?.type === "choice" ? a.probabilities?.shows : NaN;
    results[name].push(p);
    row.push(`${name} ${typeof p === "number" ? p.toFixed(2) : "?"}`);
  }
  console.log(`${item.truth ? "TRUE " : "FALSE"} ${item.obs.slice(0, 60).padEnd(60)} ${row.join("  ")}  [${json.model}]`);
}
for (const [name, ps] of Object.entries(results)) {
  const t = ps.filter((_, i) => items[i].truth === 1), f = ps.filter((_, i) => items[i].truth === 0);
  let wins = 0; for (const a of t) for (const b of f) wins += a > b ? 1 : a === b ? 0.5 : 0;
  console.log(name.padEnd(16), "AUC", (wins / (t.length * f.length)).toFixed(2), "mean true", (t.reduce((a, b) => a + b, 0) / t.length).toFixed(2), "mean false", (f.reduce((a, b) => a + b, 0) / f.length).toFixed(2));
}
EOF
