const render = (o: any, withSuggested: boolean) => withSuggested ? `${o.field}: ${o.current ?? ""} -> ${o.suggested ?? ""} (${o.reason ?? ""})` : `${o.field}: ${o.current ?? ""} (${o.reason ?? ""})`;
const ask = async (state: any, questions: any) => {
  const res = await fetch("https://api.typesafe.ai/v1/systemone", { method: "POST", headers: { "content-type": "application/json", authorization: `Bearer ${key}` }, body: JSON.stringify({ model: "jev-latest", state, questions }) });
