  const c = cases[id];
  const brief = Object.entries(c.brief.answers).map(([k, v]) => `${k}: ${v}`).join("\n");
  for (const withSuggested of [true, false]) {
    const state: any = { brief, draft: c.draftText };
    const questions: any = {};
    list.forEach((o, j) => { state[`observation${j + 1}`] = render(o, withSuggested); questions[`o${j + 1}`] = { type: "noul", instructions: `Is the problem that \`observation${j + 1}\` describes actually present in \`draft\`, judged against \`brief\`?` }; });
    const batched = await ask(state, questions);
