import { readFileSync } from "node:fs";
const account = process.env.CF_ACCOUNT!, token = process.env.CF_TOKEN!;
const rows = readFileSync(process.argv[2], "utf8").split("\n").filter(Boolean).map((l) => JSON.parse(l));
const pick = process.argv.slice(3);
const base: Record<string, string> = {
  workingTitle: "The title the writer gives the piece, or the writer's own one-sentence description of what it is.",
  format: "The kind of piece the writer says it is, such as an essay, review, speech, feature, story or email.",
  audience: "The readers the writer says the piece is for.",
  goal: "What the writer says the piece should achieve, or make its readers think or do.",
  tone: "The tone or voice the writer says they want the piece to have.",
  constraints: "A limit the writer sets on the piece: a length, venue, deadline, or something it must include or avoid.",
  successSignal: "What the writer says would show that the piece has worked.",
};
const variants = {
  base: Object.fromEntries(Object.entries(base).map(([k, v]) => [k, { type: "text", instructions: v }])),
  strict: Object.fromEntries(Object.entries(base).map(([k, v]) => [k, { type: "text", instructions: `${v} Only words the writer says. Null if the writer has not said it.` }])),
};
for (const row of rows.filter((r) => pick.includes(r.case_id))) {
  let text = "";
  for (const m of row.messages) { if (text) text += "\n\n"; text += (m.author === "writer" ? "Writer: " : "Interviewer: ") + m.text; }
  for (const [name, fields] of Object.entries(variants)) {
    const res = await fetch(`https://api.cloudflare.com/client/v4/accounts/${account}/ai/run/@cf/cloudflare/clairic`, { method: "POST", headers: { authorization: `Bearer ${token}`, "content-type": "application/json" }, body: JSON.stringify({ model: "clairic", state: text, fields }) });
    const json: any = await res.json();
