import { readFileSync } from "node:fs";
const key = process.env.TYPESAFE_API_KEY!;
const cases = Object.fromEntries(readFileSync(process.argv[2], "utf8").split("\n").filter(Boolean).map((l) => { const c = JSON.parse(l); return [c.case_id, c]; }));
const report = JSON.parse(readFileSync(process.argv[3], "utf8"));
function around(draft: string, passage: string) { const ps = draft.split(/\n\s*\n/); const at = ps.findIndex((p) => p.includes(passage.trim().slice(0, 60))); return ps.slice(Math.max(0, at - 1), at + 2).join("\n\n").slice(0, 2400); }
const fitBroken = (r: string) => "and then, the which " + r.charAt(0).toLowerCase() + r.slice(1).replace(/\.$/, "") + " of whom";
for (const c of report.cases) {
  const k = cases[c.case_id];
  for (const [label, replacement] of [["app", c.raw.replacement], ["broken", fitBroken(c.raw.replacement)]] as const) {
    const out: string[] = [];
    for (const withContext of [true, false]) {
      const state: any = { problem: k.problem, original: k.original, replacement, draft: k.draftText };
      if (withContext) state.context = around(k.draftText, k.original);
      const questions: any = {
        invents: { type: "noul", instructions: "Does `replacement` add a figure, date, name, event, study or source that `draft` does not mention? Rewording what the draft already says does not count, and neither does explaining a term." },
        fits: withContext
          ? { type: "noul", instructions: "Could `replacement` stand in place of `original` inside `context` without breaking the grammar or the flow of the sentences around it?" }
          : { type: "noul", instructions: "Could `replacement` stand in place of `original` in `draft` without breaking the grammar or the flow of the sentences around it?" },
      };
      const res = await fetch("https://api.typesafe.ai/v1/systemone", { method: "POST", headers: { "content-type": "application/json", authorization: `Bearer ${key}` }, body: JSON.stringify({ model: "jev-latest", state, questions }) });
      const a = ((await res.json()) as any).answers;
      out.push(`${withContext ? "ctx" : "draft-only"}: invents ${a.invents.noul.toFixed(2)} fits ${a.fits.noul.toFixed(2)}`);
    }
    console.log(c.case_id.padEnd(36), label.padEnd(7), out.join("   "));
  }
}
EOF
