describe("dossier", () => {
  const cases = dossierSuite.load();
  const compost = cases.find((c) => c.case_id === "dossier-goal-compost-pilot") as DossierCase;
  const observations = [
    { field: "goal", current: "never asks residents to sign up", suggested: "ask", reason: "the goal is sign-ups" },
    { field: "workingTitle", current: "reads as a history", suggested: "retitle", reason: "the title promises a call to join" },
  ];
  const clairic = (max: number | null, min: number | null = null) => {
    const requests: Array<Parameters<ClairicAsk>[0]> = [];
    const ask: ClairicAsk = async (request) => {
      requests.push(request);
      return {
        ok: true,
        answers: {
          max_words: { type: "number", value: max, p_null: max === null ? 0.9 : 0.01 },
          min_words: { type: "number", value: min, p_null: min === null ? 0.9 : 0.01 },
        },
      };
    };
    return { ask, requests };
  };

  test("field names are checked both ways, and Jev's precision request never sees the planted drifts", async () => {
    const jev = fakeJev({ noul: (id) => (id === "claims_overrun" ? 0.1 : 0.9) });
    const scores = await dossierSuite.score(
      { judge: null, jev: jev.ask, extract: clairic(600).ask },
      compost,
      { observations, provider: "rivet" },
    );
    expect(scores.field_precision.score).toBe(0.5);
    expect(scores.jev_obs_supported.items).toEqual({ o1: 0.9, o2: 0.9 });
    expect(Object.keys(scores.jev_drift_recall.items ?? {})).toHaveLength(compost.drifts.length);
    const blind = jev.requests.find((r) => "draft" in r.state)!;
    const keyed = jev.requests.find((r) => "drift1" in r.state)!;
    for (const drift of compost.drifts) expect(JSON.stringify(blind.state)).not.toContain(drift.issue.slice(0, 40));
    expect(JSON.stringify(blind.state)).not.toContain("retitle");
    expect(keyed.state.drift1).toBe(compost.drifts[0].issue);
  });

  test("a claimed overrun is checked against the word count, not the answer key", async () => {
    const words = compost.draftText.trim().split(/\s+/).length;
    const quiet = await dossierSuite.score(
      { judge: null, jev: fakeJev({ noul: (id) => (id === "claims_overrun" ? 0.1 : 0.9) }).ask, extract: clairic(600).ask },
      compost,
      { observations, provider: "rivet" },
    );
    expect(words).toBeLessThan(600);
    expect(quiet.length_claims).toMatchObject({ score: 1, label: "no false claim" });
    expect(quiet.length_claims.explanation).toContain("claim an overrun the count does not show");

    const claimed = await dossierSuite.score(
      { judge: null, jev: fakeJev({ noul: () => 0.9 }).ask, extract: clairic(500).ask },
      compost,
      { observations, provider: "rivet" },
    );
    expect(claimed.length_claims).toMatchObject({ score: 1, label: "caught overrun" });

    const falseAlarm = await dossierSuite.score(
      { judge: null, jev: fakeJev({ noul: () => 0.9 }).ask, extract: clairic(null).ask },
      compost,
      { observations, provider: "rivet" },
