import { readReports, bySuite } from "/home/diogenes/Projects/apps/twyne/evals/app/reports";
import { summarizeCases, comparePaired, tCritical } from "/home/diogenes/Projects/apps/twyne/evals/app/stats";
const R = "/home/diogenes/Projects/apps/twyne/reports/app-evals/";
const fixed = bySuite(readReports([R + "notorganic-fixed-20261023"]));
const full = bySuite(readReports([R + "notorganic-full-20261023"]));
const sizes: Record<string, number> = { room: 45, rubric: 16, rewrite: 24, interview: 10 };
for (const suite of ["room", "rubric", "rewrite", "interview"]) {
  const now = fixed.get(suite)![0], before = full.get(suite)![0];
  const summary = summarizeCases(suite, now.cases);
  const cmp = comparePaired(suite, before.cases, now.cases);
  const units = sizes[suite];
  console.log(`\n${suite}: today n=${now.cases.length}; projected at ${units} ${suite === "rubric" ? "pairs" : "cases"}`);
  console.log(`  ${"metric".padEnd(24)} mean   ±CI now   sd(case)  ±mean@N   sd(Δ paired)  ±Δ paired now  ±Δ paired@N`);
  for (const [name, s] of Object.entries(summary)) {
    if (s.mean === null || !s.ci) continue;
    const m = cmp.metrics.find((x) => x.metric === name);
    const half = (s.ci[1] - s.ci[0]) / 2;
    const sdUnit = s.se && s.clusters ? s.se * Math.sqrt(s.clusters) : null;
    const projMean = sdUnit !== null ? 1.96 * sdUnit / Math.sqrt(units) : null;
    const dHalf = m?.ci ? (m.ci[1] - m.ci[0]) / 2 : null;
    const sdDelta = dHalf !== null && m ? dHalf / tCritical(m.clusters - 1) * Math.sqrt(m.clusters) : null;
    const projDelta = sdDelta !== null ? 1.96 * sdDelta / Math.sqrt(units) : null;
    const f = (x: number | null) => (x === null || !Number.isFinite(x) ? "   -  " : x.toFixed(3).padStart(6));
    console.log(`  ${name.padEnd(24)} ${s.mean.toFixed(2)}   ${f(half)}    ${f(sdUnit)}   ${f(projMean)}      ${f(sdDelta)}        ${f(dHalf)}        ${f(projDelta)}`);
  }
}
EOF
cd /home/diogenes/Projects/apps/twyne && bun /tmp/twyne-stats/project.ts 2>&1

